insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('palenque-mexico', '10S', 'Palenque, Mexico', 'Mexico', 'Palenque', 'live', 'verified', 'mountainValley', 'Chiapas (San Cristóbal & Palenque)', '{"culture","expedition"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L3","gate_result":"BOOK WITH WARNING","book_enabled":true,"bin":"BOOK WITH WARNING","consent_flow":true,"content_only":false,"redirect_eligible":false,"air_access_verified":{"PQM_palenque":"non-operational since ~2020 — do not route","VSA_villahermosa":"primary gateway, ~2–2.5 hr / ~82 mi to Palenque","TGZ_tuxtla":"serves San Cristóbal end of corridor"},"road_access_flag":true,"road_note":"San Cristóbal↔Palenque via Ocosingo (Chilón) — documented armed-robbery history; daytime-only, guided/convoy transfer, no self-drive, prefer VSA approach"},"timing":{"peak":"Nov–Apr (dry season, jungle passable, waterfalls turquoise)","inflection":"early–mid September","fire_date":"late August (curve-start − 1–2 weeks)","off_season":"May–Oct rainy — brown water, muddy roads, higher road risk"},"jewels":[{"name":"Temple of the Inscriptions + Pakal''s pyramid","si_tag":"culture","tier":"essential","commission_path":"guided-tour DMC/affiliate (admission non-commissionable)","source":"https://mayaruins.com/palenque/a1_223.html","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the anchor. Tomb descent closed since ~2004; regalia at the site museum","si":"culture","blurb":"the anchor. Tomb descent closed since ~2004; regalia at the site museum","when":"year-round","commission":"guided-tour DMC/affiliate (admission non-commissionable)"},{"name":"The Palace + observation tower","si_tag":"culture","tier":"essential","commission_path":"guided-tour affiliate","source":"https://www.mexicotravelandleisure.com/blog/palenque-ruins-guide/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the four-story tower is Palenque''s signature silhouette; the Palace complex is the civic heart of the site","si":"culture","blurb":"the four-story tower is Palenque''s signature silhouette; the Palace complex is the civic heart of the site","when":"year-round","commission":"guided-tour affiliate"},{"name":"Site Museum + Pakal reconstructed tomb exhibit","si_tag":"culture","tier":"essential","commission_path":"bundled admission (non-commissionable)","source":"https://mayaruins.com/palenque/a1_223.html","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"bundled admission (non-commissionable)"},{"name":"Bonampak murals (~792 AD)","si_tag":"culture","tier":"comfort","commission_path":"full-day DMC tour","source":"https://www.viator.com/tours/Palenque/Tour-Bonampak-and-Yaxchilan/d23479-30922P9","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"best-preserved Classic Maya murals on Earth, full-color three-room cycle","si":"culture","blurb":"best-preserved Classic Maya murals on Earth, full-color three-room cycle","when":"Nov–Apr","commission":"full-day DMC tour"},{"name":"Yaxchilán by Usumacinta riverboat","si_tag":"culture","tier":"premier","commission_path":"licensed river-tour DMC (border-verify)","source":"https://www.viator.com/tours/Palenque/Tour-Bonampak-and-Yaxchilan/d23479-30922P9","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Usumacinta motorboat into the Lacandón, ruins the road cannot reach","si":"culture","blurb":"Usumacinta motorboat into the Lacandón, ruins the road cannot reach","when":"Nov–Apr","commission":"licensed river-tour DMC (border-verify)"},{"name":"Agua Azul cascades","si_tag":"expedition","tier":"essential","commission_path":"waterfall day-tour affiliate","source":"https://www.viator.com/tours/Palenque/Agua-Azul-and-Misol-Ha/d23479-30922P10","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Nov–Apr","commission":"waterfall day-tour affiliate"},{"name":"Misol-Ha waterfall (Predator site)","si_tag":"expedition","tier":"essential","commission_path":"day-tour affiliate","source":"https://www.mexicotravelandleisure.com/blog/things-to-do-in-palenque/","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Nov–Apr","commission":"day-tour affiliate"},{"name":"Roberto Barrios cascades","si_tag":"expedition","tier":"essential","commission_path":"dedicated day-tour affiliate","source":"https://nomadearthcatalog.com/cascadas-roberto-barrios/","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"five off-the-beaten-track falls, turquoise pools, natural 10 m slide, ~45 min south, entry ~30 MXN","si":"expedition","blurb":"five off-the-beaten-track falls, turquoise pools, natural 10 m slide, ~45 min south, entry ~30 MXN","when":"Nov–Apr","commission":"dedicated day-tour affiliate"},{"name":"Howler-monkey jungle canopy (dawn ruins)","si_tag":"expedition","tier":"comfort","commission_path":"guided dawn tour upsell","source":"https://www.timetravelturtle.com/mexico/visit-palenque/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the sound that defines dawn at Palenque; the ruins double as a wildlife encounter","si":"expedition","blurb":"the sound that defines dawn at Palenque; the ruins double as a wildlife encounter","when":"year-round","commission":"guided dawn tour upsell"},{"name":"Lacandón Jungle multi-day expedition","si_tag":"expedition","tier":"premier","commission_path":"multi-day DMC","source":"https://mayantourstravel.com/tours/the-amazing-lacandon-jungle-groups/","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"deep-forest circuit combining Bonampak, Yaxchilán and river camps","si":"expedition","blurb":"deep-forest circuit combining Bonampak, Yaxchilán and river camps","when":"Nov–Apr","commission":"multi-day DMC"}],"faq":[{"q":"Is Palenque safe to visit given the Chiapas Level 3 advisory?","a":"Yes, with an informed booking. Chiapas is US State Dept Level 3 \"Reconsider Travel,\" but the restricted no-go zone runs along the Guatemala border and terminates at Ocosingo — Palenque, San Cristóbal and Tuxtla Gutiérrez all sit outside it, with no US-government travel ban. TravelWell books it with the full Level 3 disclosure and routes travelers in by air through Villahermosa (VSA), never the overland danger road.","source":"travel.state.gov, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for — is the road dangerous?","a":"The road is the risk, not the ruins. The overland San Cristóbal↔Palenque highway via Ocosingo (Chilón) has a documented armed-robbery history — one reported incident had ~18 men with assault rifles set a roadblock and rob a line of tourist vehicles, with the worst incidents after dark. The rule is daytime-only, guided/convoy transfer, no self-drive, and the safer, longer Villahermosa toll-road approach where possible.","source":"mexiconewsdaily.com / jeniastraveldiaries.com, 2026-07-07","si_tag":"safety"},{"q":"How remote is medical care from Palenque?","a":"Genuinely remote — plan for it. Palenque is a small town with limited advanced care; serious trauma routes to Villahermosa or Tuxtla Gutiérrez, with air evacuation to Mexico City for anything major. Bonampak, Yaxchilán and the deep-jungle waterfalls are hours from a hospital, so carry evacuation insurance — and note dengue is present year-round with malaria risk in rural Chiapas.","source":"mexiconewsdaily.com, 2026-07-07","si_tag":"safety"},{"q":"What will I see at the Palenque ruins?","a":"A Maya city the rainforest never fully released: the Temple of the Inscriptions rising over Pakal the Great''s tomb, and the four-story observation tower of the Palace, its civic heart. The tomb chamber itself has been closed to descent since ~2004 to protect it, so you see the pyramid and Pakal''s regalia at the site museum, not the crypt. Go at the 8 AM opening before the jungle heat.","source":"mayaruins.com, 2026-07-07","si_tag":"culture"},{"q":"What are the Palenque waterfalls, and when should I go?","a":"Three systems within reach: Agua Azul''s 500+ turquoise cascades over ~6 km, the ~35 m Misol-Ha plunge with a walk-behind grotto, and the quieter Roberto Barrios falls with a natural rock slide (~45 min south, entry ~30 MXN). Come November–April, when the mineral-rich water runs brilliant turquoise; in the May–October rains sediment turns Agua Azul brown. Swim only in marked zones — currents are strong.","source":"mexicotravelandleisure.com, 2026-07-07","si_tag":"expedition"},{"q":"Can I visit Bonampak and Yaxchilán?","a":"Yes, as a full-day guided expedition. Bonampak holds the best-preserved Classic Maya murals in existence (~792 AD), and Yaxchilán is reachable only by motorboat on the Usumacinta River, the water border with Guatemala. Go with a licensed operator, not an ad-hoc boatman, verify current border and security conditions before booking, and travel by daylight with life vests.","source":"viator.com, 2026-07-07","si_tag":"culture"}],"seo":{"meta_title":"Palenque, Mexico: Jungle Maya Ruins, Waterfalls & Safe Travel Guide (2026) | TravelWell","search_language":"es-MX","local_keywords":["ruinas de Palenque","Agua Azul Chiapas","Misol-Ha","Yaxchilán Bonampak","cascadas Roberto Barrios","Templo de las Inscripciones Pakal","cómo llegar a Palenque desde Villahermosa"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","primary_keyword":"Palenque"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"},{"si":"expedition","status":"live"}],"ultra":[{"name":"Chan-Kah Resort Village","tier":"premier","mor":"bedbank/direct","earning":"modest — upper-mid ADR, not luxury; live"},{"name":"Boutique Quinta Chanabnal","tier":"premier","mor":"advisor/direct","earning":"modest"},{"name":"Piedra de Agua Palenque","tier":"comfort","mor":"verify","earning":"to verify"}],"source_verified":null,"hero":{"query":"Palenque, Mexico, Mexico"},"geo":{"lat":17.484,"lng":-92.046}}'::jsonb, 76),
  ('pantanal-brazil', '10S', 'The Pantanal, Brazil', 'Brazil', 'The Pantanal', 'live', 'verified', 'safariJeep', 'Amazon, Pantanal & Iguaçu', '{"safari","wildlife","expedition"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","emergency_secondary":["193 fire/environmental","192 SAMU medical"],"advisory_level":"L2","advisory_note":"L2 (Brazil) — Pantanal exempted; route to the park","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"air_access":{"north":"CGB (Cuiabá) — Porto Jofre / Transpantaneira","south":"CGR (Campo Grande) — Caiman / Southern reserves"},"remote_flag":true,"medevac_note":"hours by dirt road + river to trauma care (Cuiabá north / Campo Grande south); comprehensive insurance w/ medical evacuation is a standard attach","health":{"malaria":"low; zone-dependent (present in parts of state of Mato Grosso / Northern; NOT in Cuiabá city nor Mato Grosso do Sul / Southern)","dengue_chikungunya":"flag — present; insect protection regardless of malaria zone","yellow_fever":"vaccination recommended for Mato Grosso"},"wildlife_water_rules":["life vests on all boat safaris","no-approach / minimum-distance on jaguars","no swimming in caiman/piranha waters","stay in vehicle/boat","no feeding or baiting"]},"timing":{"peak":"Dry season Jul-Oct; jaguar optimum late Jul-early Oct; strongest Aug-Sep","birding":"year-round; jabiru nesting Jul-early Nov; wading-bird flocks late Jul-mid-Aug","high_water_green_season":"Dec-Mar (rivers highest, jaguars dispersed, lush + cheaper)","inflection":"demand loads 6+ months ahead of dry season; premium Porto Jofre beds scarce","fire_date":"curve-start minus 1-2 weeks; fire in Nov-Jan of prior season for the Jul-Oct jaguar peak","advance_book_note":"jaguar-season lodges (floating suites, mobile camps, top river lodges) book 6+ months out for Aug-Sep","off_season_fill":"green season Dec-Mar sold on price + birding + photography + fewer boats"},"jewels":[{"name":"Porto Jofre jaguar boat safari","si_tag":"safari","tier":"premier","commission_path":"operator/DMC packaged boat-safari + full-board lodge","source":"https://www.flashpackerconnect.com/blog/the-ultimate-guide-to-jaguar-viewing-tours-in-brazils-pantanal","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Small open boats on the Cuiabá/Piquirí/Três Irmãos rivers. Guide-required","si":"safari","blurb":"Small open boats on the Cuiabá/Piquirí/Três Irmãos rivers. Guide-required","when":"Dry season Jul-Oct","commission":"operator/DMC packaged boat-safari + full-board lodge"},{"name":"Transpantaneira road safari (Poconé to Porto Jofre)","si_tag":"safari","tier":"comfort","commission_path":"DMC transfer-as-safari + Transpantaneira lodges","source":"https://www.oneroadtrip.com/itineraries/br-mato-grosso-pantanal-nord-jaguar-6j.html","timing":"year-round","timing_type":"ALWAYS-ON","hook":"The 147 km / 122-bridge causeway is itself a rolling game drive — caiman, capybara, jabiru, tapir, and macaw from the vehicle","si":"safari","blurb":"The 147 km / 122-bridge causeway is itself a rolling game drive — caiman, capybara, jabiru, tapir, and macaw from the vehicle","when":"year-round","commission":"DMC transfer-as-safari + Transpantaneira lodges"},{"name":"Giant otter tracking","si_tag":"safari","tier":"comfort","commission_path":"lodge boat-safari program","source":"https://www.pantanaljaguarsafaris.com/best-time-to-visit","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Giant otters seen daily and close-range on the rivers June–December — a charismatic, near-guaranteed dry-season jewel","si":"safari","blurb":"Giant otters seen daily and close-range on the rivers June–December — a charismatic, near-guaranteed dry-season jewel","when":"Dry season Jul-Oct","commission":"lodge boat-safari program"},{"name":"Night drive (nocturnal wildlife)","si_tag":"safari","tier":"comfort","commission_path":"lodge-included activity","source":"https://www.brazilnaturetours.com/vacation-packages/pantanal","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Spotlight drives for ocelot, tapir, and nightlife the day misses","si":"safari","blurb":"Spotlight drives for ocelot, tapir, and nightlife the day misses","when":"Dry season Jul-Oct","commission":"lodge-included activity"},{"name":"Horseback pantaneiro ride (Southern)","si_tag":"safari","tier":"premier","commission_path":"lodge-included / Southern DMC","source":"https://www.amazonadventures.com/caiman-ecological-refuge.html","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Ride the open grassland with the working cowboys — a genuine Southern-Pantanal signature","si":"safari","blurb":"Ride the open grassland with the working cowboys — a genuine Southern-Pantanal signature","when":"Dry season Jul-Oct","commission":"lodge-included / Southern DMC"},{"name":"Caiman & capybara mega-concentrations","si_tag":"safari","tier":"essential","commission_path":"included in every lodge program","source":"https://www.wildlifeworldwide.com/locations/the-pantanal","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The thousands-strong yacaré caiman gatherings and the ubiquitous capybara are the base layer of every drive and boat — the wetland''s signature density","si":"safari","blurb":"The thousands-strong yacaré caiman gatherings and the ubiquitous capybara are the base layer of every drive and boat — the wetland''s signature density","when":"Dry season Jul-Oct","commission":"included in every lodge program"},{"name":"Mobile tented jaguar camp","si_tag":"expedition","tier":"premier","commission_path":"specialist expedition-operator net","source":"https://www.pantanaljaguarsafaris.com/","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Expedition-style tented camping in the heart of the jaguar zone — the harder-core, closer-to-the-wild alternative to a fixed lodge","si":"expedition","blurb":"Expedition-style tented camping in the heart of the jaguar zone — the harder-core, closer-to-the-wild alternative to a fixed lodge","when":"Dry season Jul-Oct","commission":"specialist expedition-operator net"},{"name":"Self-drive Transpantaneira expedition","si_tag":"expedition","tier":"essential","commission_path":"4x4 rental + a-la-carte lodge nights (thin; sell insurance attach)","source":"https://www.wildjunket.com/pantanal-jaguar-safari-brazil/","timing":"year-round","timing_type":"ALWAYS-ON","hook":"The DIY edge-of-the-map drive — 4x4, fuel from Poconé, 122 bridges, no services. A GEA-flavored adventure for the self-sufficient traveler","si":"expedition","blurb":"The DIY edge-of-the-map drive — 4x4, fuel from Poconé, 122 bridges, no services. A GEA-flavored adventure for the self-sufficient traveler","when":"year-round","commission":"4x4 rental + a-la-carte lodge nights (thin; sell insurance attach)"},{"name":"Hyacinth macaw viewing","si_tag":"wildlife","tier":"premier","commission_path":"lodge-included birding activity","source":"https://www.scottdunn.com/us/brazil/hotels/araras-eco-lodge","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The world''s largest flying parrot, reliably seen around Northern lodges like Araras — an electric-blue signature bird","si":"wildlife","blurb":"The world''s largest flying parrot, reliably seen around Northern lodges like Araras — an electric-blue signature bird","when":"Dry season Jul-Oct","commission":"lodge-included birding activity"},{"name":"Jabiru stork nesting & wading-bird flocks","si_tag":"wildlife","tier":"comfort","commission_path":"birding-specialist DMC / lodge program","source":"https://www.pantanaljaguarsafaris.com/best-time-to-visit","hook":"Jabiru nesting Jul–early Nov; massive wading-bird gatherings late Jul–mid-Aug. A world-class birding jewel","si":"wildlife","blurb":"Jabiru nesting Jul–early Nov; massive wading-bird gatherings late Jul–mid-Aug. A world-class birding jewel","commission":"birding-specialist DMC / lodge program"},{"name":"Piranha fishing","si_tag":"wildlife","tier":"essential","commission_path":"lodge-included excursion","source":"https://www.brazilnaturetours.com/vacation-packages/pantanal","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","when":"Dry season Jul-Oct","commission":"lodge-included excursion"},{"name":"650+ bird / 120+ mammal biodiversity immersion","si_tag":"wildlife","tier":"comfort","commission_path":"birding-specialist DMC multi-day land package","source":"https://www.wildlifeworldwide.com/locations/the-pantanal","timing":"Dry season Jul-Oct","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"For the dedicated naturalist, the sheer species list is the jewel — multi-day birding-and-mammal itineraries across both Pantanals","si":"wildlife","blurb":"For the dedicated naturalist, the sheer species list is the jewel — multi-day birding-and-mammal itineraries across both Pantanals","when":"Dry season Jul-Oct","commission":"birding-specialist DMC multi-day land package"}],"faq":[{"q":"When is the best time to see jaguars in the Pantanal?","a":"The dry season, roughly June–October, is the whole game: falling water concentrates wildlife on the riverbanks, and late July through early October is the optimum, with August–September the strongest months — Porto Jofre boat-safari sightings run 80–90% over a multi-day trip.","source":"pantanaljaguarsafaris.com, 2026-07-07","si_tag":"safari"},{"q":"Can you self-drive the Transpantaneira?","a":"Yes, but it''s higher-risk and guided is strongly preferred: a 4x4 is recommended for the 122 wooden bridges, you must fill fuel in Poconé because there are no stations after it, and with no services or cell coverage you must plan the medevac gap yourself.","source":"wildjunket.com, 2026-07-07","si_tag":"expedition"},{"q":"Is the Pantanal good for birding?","a":"Exceptionally, and year-round: the wetland lists 650+ bird species, with jabiru storks nesting July–early November and the biggest wading-bird flocks gathering late July to mid-August — a birding counterweight that props up the shoulders of the jaguar season.","source":"wildlifeworldwide.com, 2026-07-07","si_tag":"wildlife"},{"q":"Can the Pantanal work for a honeymoon?","a":"Yes, as a wild-honeymoon rather than a beach one: SouthWild''s Jaguar Suites are 30 m² glass-walled floating rooms with AC and WiFi anchored in the jaguar zone, boats leaving from the deck — private guiding and sundowners over the wetland for the couple who wants adventure over sand.","source":"southwild.com, 2026-07-07","si_tag":"romance"},{"q":"Is the Pantanal safe to visit right now?","a":"Yes, when routed to the park: Brazil is Level 2, and while the 160 km/100 mi border strip carries a Level 4, the Pantanal National Park is explicitly exempted — the State Department names it alongside Foz do Iguaçu as allowed. The real risks here are environmental and medical (remoteness), not criminal. `book_enabled = true`.","source":"travel.state.gov, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for in the Pantanal?","a":"Wildfire in the late dry season: 2020 fires burned about 31% of the wetland and affected roughly 45% of the jaguar population, and 2024 brought the worst fire count since records began in 1999 — well over a million hectares. Monitor fire and air-quality conditions for late-dry departures and keep flexible-rebooking language in the flow.","source":"news.mongabay.com, 2026-07-07; fireandsafetyjournalamericas.com, 2026-07-07","si_tag":"safety"},{"q":"Do I need vaccinations or malaria pills for the Pantanal?","a":"It''s zone-dependent: CDC notes malaria risk in parts of the state of Mato Grosso (Northern Pantanal) but not in Cuiabá city or Mato Grosso do Sul (Southern Pantanal), so route the health note by access door; yellow-fever vaccination is recommended for Mato Grosso, and dengue/chikungunya precautions apply regardless of malaria zone.","source":"jmbeetravelhealth.com, 2026-07-07; cdc.gov, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"The Pantanal, Brazil — World''s Best Jaguar Safari & Wildlife Wetland | TravelWell.World","meta_description":"Plan a Pantanal jaguar safari: the world''s best wild-jaguar viewing at Porto Jofre, dry-season timing, Northern vs Southern access, eco-lodges by tier, and safety. Freely bookable.","search_language":"pt-BR","long_tail_en":["best time to see jaguars in the Pantanal","Pantanal jaguar safari Porto Jofre","Transpantaneira road self-drive","Northern vs Southern Pantanal","Pantanal eco lodges by tier","hyacinth macaw Pantanal birding","jaguar flotel Porto Jofre","Caiman Ecological Refuge Onçafari"],"local_keywords":["Pantanal onças","safári de onça-pintada","Porto Jofre","Transpantaneira","onça-pintada Pantanal","melhor época para ver onças no Pantanal","pousadas Pantanal","arara-azul Pantanal","Pantanal norte e sul"],"hreflang":["en","pt-BR"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","primary_keyword":"The Pantanal"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"safari","status":"live"},{"si":"wildlife","status":"live"},{"si":"expedition","status":"live"}],"ultra":[{"name":"Caiman Ecological Refuge","location":"Southern Pantanal (~236 km from Campo Grande)","note":"53,000 ha, 3 lodges (Casa Caiman/Cordilheira/Baiazinha); Onçafari jaguar-habituation project","earning":"preferred-agent / consortium net + amenity","mor":"agent on land package","tier":"ultra"},{"name":"Fazenda Barranco Alto","location":"Southern Pantanal","note":"11,000 ha owner-run exclusive-use wildlife lodge","earning":"consortium/specialist net","mor":"agent on package","tier":"ultra"},{"name":"Araras Eco Lodge","location":"Northern Pantanal (Transpantaneira lane)","note":"~3,000+ ha private land, hyacinth-macaw territory, UNESCO setting","earning":"operator net / agent commission","mor":"agent on land package","tier":"premier"},{"name":"SouthWild Jaguar Flotel & Jaguar Suites","location":"Porto Jofre (floating, Piquirí River)","note":"floating hotels in jaguar zone; AC/WiFi/30 m2 rooms; boats from the deck","earning":"SouthWild net / tour-operator terms","mor":"agent on package","tier":"ultra"},{"name":"Mobile tented jaguar camp","location":"Porto Jofre core","note":"expedition-grade seasonal tented camping in jaguar zone","earning":"specialist expedition-operator net","mor":"agent","tier":"ultra"}],"source_verified":null,"hero":{"query":"The Pantanal, Brazil, Brazil"},"geo":{"lat":-16.35,"lng":-56.6667}}'::jsonb, 77),
  ('paracas-nazca-peru', '10S', 'Paracas, Nazca & the South Coast', 'Peru', '*If it''s a desert oasis, a "poor man''s Galápagos,"', 'live', 'verified', 'desertDunes', 'Lima, South Coast & Amazon', '{"expedition","culture","culinary"}', '{}', '{"essential","comfort","premier","luxury"}', null, null, '{"key_facts":["The South Coast is a desert-and-ocean circuit ~3–4 hr south of Lima on the Panamericana Sur — no altitude, no cloud-forest; the risks are activity/operator, not crime.","Ballestas Islands (''poor man''s Galápagos'') — sea lions, Humboldt penguins, boobies, 150+ bird species — visitable only by ~2-hr guided boat from El Chaco pier.","Nazca Lines are best seen on a ~30–35 min light-aircraft overflight from María Reiche Neuman aerodrome (NZC) — choose a reputable operator (accident history; 2022 fatal crash) and expect banking-turn motion sickness.","Huacachina is a real palm-ringed desert oasis outside Ica; the marquee is the sunset dune-buggy + sandboard circuit — ride only permitted buggies (four-point belts + roll cages).","Paracas National Reserve (~S/11 entry) has Playa Roja (Red Beach) and La Catedral; swimming is prohibited at Playa Roja (open swell, strong currents, no lifeguards)."],"safety":{"emergency":"105","emergency_ambulance":"117","emergency_fire":"116","tourist_line":"iPerú / Policía de Turismo","hospital":"Ica & Pisco clinics for routine/stabilization; serious cases evac to Lima (Clínica Anglo Americana / Ricardo Palma); desert stretches remote","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","consent_flow_required":false,"air_access_verified":true,"air_access_note":"Fly Lima (LIM); road ~3–4 hr south on the Panamericana Sur to Paracas/Ica; Nazca overflights depart María Reiche Neuman aerodrome (NZC)","activity_flags":{"nazca_overflight":"reputable/authorized operator only (accident history; 2022 fatal crash); small-plane turbulence + motion sickness; weather-suspension risk (wind/dust/garua)","huacachina_dune_buggy":"rollover risk; permitted operators only (four-point belts, roll cages, headrests, certified welds, <=15-yr vehicles); avoid informal ''tubular'' buggies","ballestas_boat":"open-ocean swell; life vests provided and worn","pacific_coast":"riptides, strong currents, no lifeguards; Playa Roja swimming prohibited; railing-less cliffs at La Catedral","wind_sport":"May–Sep kitesurf — school + PFD, offshore-wind hazard"},"sun":"high desert UV — sunscreen, hats, hydration","water":"bottled/purified only","malaria":"none on the arid South Coast (malaria risk is the low-elevation Amazon)"},"timing":{"peak":"December–April (Peruvian summer, hot/sunny; beach + desert; Paracas year-round as Lima escape)","event_peak":"Ica Vendimia grape-harvest festival — first weeks of March","inflection_curve_start":"summer: late Oct–early Nov; Vendimia: mid-to-late January","fire_date":"2026-10-20 (summer peak) / 2026-01-15 (Vendimia) — each = curve-start − 1–2 weeks","wind_sport_window":"May–September (winter; stronger Paracas winds; kitesurf; clearer Nazca skies but garua/gust flight-suspension risk)","shoulder":"April–May & October–November (best value)","booking_lead":"core circuit days–weeks; Huacachina sunset/weekend buggy 2–3 days; Vendimia + Dec–Apr Paracas resorts weeks–months","off_season":"winter wind-sport + shoulder value stays + year-round Lima day-trip/overnight bundles","event_peaks":["Ica Vendimia (grape-harvest festival), March"]},"jewels":[{"name":"Ballestas Islands (''poor man''s Galápagos'')","si_tag":"GEA","status":"live","hook":"Sea lions, Humboldt penguins, boobies & 150+ bird species under guano cliffs — 20 min off the pier","bookable_category":"guided_boat_tour","tier":"essential","commission_path":"boat operator via OutsideAgents/affiliate (embarkation fee non-commissionable)","source":"https://www.alongdustyroads.com/posts/islas-ballestas-tour-paracas","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"Sea lions, Humboldt penguins, boobies & 150+ bird species under guano cliffs — 20 min off the pier","when":"December–April","commission":"boat operator via OutsideAgents/affiliate (embarkation fee non-commissionable)"},{"name":"Nazca Lines overflight + María Reiche viewpoint","si_tag":"GEA","status":"live","hook":"Bank over 2,000-year-old geoglyphs only the sky can read — hummingbird, monkey, spider, condor","bookable_category":"licensed_overflight","tier":"premier","commission_path":"authorized/reputable overflight operator via OutsideAgents (airport tax + site ticket non-commissionable)","source":"https://howtoperu.com/answers/nazca-lines-tower-vs-plane-costs-safety-cancellations/","timing":"year-round","timing_type":"ALWAYS-ON","si":"GEA","blurb":"Bank over 2,000-year-old geoglyphs only the sky can read — hummingbird, monkey, spider, condor","when":"year-round","commission":"authorized/reputable overflight operator via OutsideAgents (airport tax + site ticket non-commissionable)"},{"name":"Huacachina oasis — dune-buggy + sandboard sunset","si_tag":"GEA","status":"live","hook":"Roller-coaster the dunes, then slide back down into the sunset from a real desert oasis","bookable_category":"dune_buggy_sandboard","tier":"essential","commission_path":"permitted buggy operator via OutsideAgents/affiliate","source":"https://bushop.com/peru/guides/huacachina-dune-buggy-sandboarding-prices-safety-and-best-time-of-day/","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"Roller-coaster the dunes, then slide back down into the sunset from a real desert oasis","when":"December–April","commission":"permitted buggy operator via OutsideAgents/affiliate"},{"name":"Paracas National Reserve — Playa Roja & La Catedral","si_tag":"GEA","status":"live","hook":"A crimson beach the color of Mars against yellow cliffs and a teal Pacific — look, don''t swim","bookable_category":"reserve_day_tour","tier":"essential","commission_path":"reserve day-tour via OutsideAgents/affiliate (S/11 entry non-commissionable)","source":"https://www.paracasperu.com/guides/paracas-national-reserve-wildlife-hiking-park-entrance-guide/","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"A crimson beach the color of Mars against yellow cliffs and a teal Pacific — look, don''t swim","when":"December–April","commission":"reserve day-tour via OutsideAgents/affiliate (S/11 entry non-commissionable)"},{"name":"Chauchilla Cemetery","si_tag":"Culture & Heritage","status":"future","hook":"Naturally mummified Nazca-culture bodies in their original open desert tombs, textiles intact","bookable_category":"ground_tour_addon","tier":"comfort","commission_path":"Nazca DMC/tour operator via OutsideAgents","source":"https://en.wikipedia.org/wiki/Chauchilla_Cemetery","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Naturally mummified Nazca-culture bodies in their original open desert tombs, textiles intact","when":"year-round","commission":"Nazca DMC/tour operator via OutsideAgents"},{"name":"Tambo Colorado (Pisco valley)","si_tag":"Culture & Heritage","status":"future","hook":"One of the best-preserved coastal Inca sites — adobe walls still red, the Spanish never wrecked it","bookable_category":"guided_excursion","tier":"comfort","commission_path":"guided excursion from Paracas/Pisco via OutsideAgents","source":"https://en.wikipedia.org/wiki/Tambo_Colorado","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"One of the best-preserved coastal Inca sites — adobe walls still red, the Spanish never wrecked it","when":"December–April","commission":"guided excursion from Paracas/Pisco via OutsideAgents"},{"name":"Paracas Candelabra geoglyph","si_tag":"Culture & Heritage","status":"future","hook":"A 170 m desert trident visible 19 km out to sea — seen at the start of the Ballestas boat tour","bookable_category":"included_in_boat_tour","tier":"essential","commission_path":"included in Ballestas boat tour (affiliate)","source":"https://en.wikipedia.org/wiki/Paracas_Candelabra","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"A 170 m desert trident visible 19 km out to sea — seen at the start of the Ballestas boat tour","when":"December–April","commission":"included in Ballestas boat tour (affiliate)"},{"name":"Ica pisco bodegas + Vendimia","si_tag":"Culinary","status":"future","hook":"Stand where Peruvian pisco was born — Tacama, El Catador, Queirolo — and tread the grapes each March","bookable_category":"wine_pisco_tour","tier":"comfort","commission_path":"Ica DMC/wine-tour operator via OutsideAgents/Fora","source":"https://quechuasperuviajes.com/festival-de-la-vendimia-de-ica","timing":"December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"Stand where Peruvian pisco was born — Tacama, El Catador, Queirolo — and tread the grapes each March","when":"December–April","commission":"Ica DMC/wine-tour operator via OutsideAgents/Fora"}],"faq":[{"q":"Is the Nazca Lines flight worth it, and is it safe?","a":"Worth it — it''s the only way to truly read the geoglyphs — but operator choice is load-bearing. The ~30–35 min flight from María Reiche (NZC) runs ~US$85–120 plus taxes; the route has an accident history (a fatal crash as recently as 2022), so book only authorized carriers with a clean record, take an early slot and eat light against banking-turn motion sickness.","source":"howtoperu.com, 2026-07-07","si_tag":"expedition"},{"q":"Can you swim at the Paracas beaches?","a":"Not at the reserve beaches. Playa Roja and the reserve coast have open swell, strong currents and no lifeguards — swimming is prohibited at Playa Roja, and the cliffs at La Catedral are crumbly and railing-less. Safe bay swimming is at the resort waterfronts, not inside the reserve (~S/11 entry).","source":"paracasperu.com, 2026-07-07","si_tag":"tropical"},{"q":"How old are the Nazca Lines, and what will I see?","a":"They date to the Nazca culture ~300–600 AD. From a ~30–35 min overflight you''ll pick out the hummingbird, monkey, spider and condor cut into the desert at a scale invisible from the ground; a roadside mirador shows 2–3 figures for those who''d rather not fly.","source":"howtoperu.com, 2026-07-07","si_tag":"culture"},{"q":"What''s the Ica Vendimia and pisco scene?","a":"Ica is the cradle of Peruvian pisco and wine. Historic bodegas — Tacama, Vista Alegre, El Catador, Ocucaje, Queirolo/Intipalka — run tastings year-round, peaking at the March Vendimia grape-harvest festival with 40+ activities, grape-treading and tastings across the city.","source":"quechuasperuviajes.com, 2026-07-07","si_tag":"culinary"},{"q":"Is Paracas, Ica and Nazca safe right now?","a":"Yes — freely bookable. Peru is Level 2 nationwide, and the Ica department (Paracas, the Ballestas, Huacachina, Ica city, Nazca) is not inside any Level 3 or Level 4 carve-out; the higher-risk VRAEM and Loreto/Colombia border are geographically separate. The real risks here are activity and operator choice, not violent crime.","source":"paracasperu.com, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"Activity safety and operator choice, not crime. The load-bearing calls are the Nazca light-aircraft overflight (authorized operators only; 2022 fatal crash), the Huacachina dune-buggy (rollover risk), Ballestas boat life-vests and Pacific riptides. High winds/dust and winter garúa can also suspend flights.","source":"howtoperu.com, 2026-07-07","si_tag":"safety"},{"q":"Is the Huacachina dune buggy dangerous?","a":"It carries real rollover risk on the steep dunes, so operator choice matters. Peru''s minimum standard requires four-point seatbelts, roll cages, headrests, certified welds and a 15-year max vehicle age; the transport ministry has warned against informal \"tubular\" buggies. Ride only permitted operators and check your belts.","source":"bushop.com, 2026-07-07","si_tag":"safety"}],"seo":{"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-07","meta_title":"Paracas, Nazca & Peru''s South Coast — Ballestas, Nazca Lines, Huacachina Dunes & When to Go (2026)","search_language":"es-PE","local_keywords":["Islas Ballestas tour","Líneas de Nazca sobrevuelo","Huacachina oasis","Paracas","Reserva Nacional de Paracas Playa Roja","tubular Huacachina sandboard","bodegas de pisco Ica","Festival de la Vendimia Ica","Tambo Colorado Pisco","cementerio de Chauchilla","Candelabro de Paracas"],"hreflang":["en","es-PE"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"culinary","status":"future"}],"ultra":[{"name":"Hotel Paracas, a Luxury Collection Resort (Marriott)","why_ultra":"Bay''s marquee 5-star — private dock, spa, standout dining, secluded rooms facing the reserve","earning":"Marriott/Luxury Collection commission via Fora/Virtuoso (or STARS/Luminous)","virtuoso_value_add":"STARS/Virtuoso perks: breakfast, property credit, upgrades; private boat/reserve arrangements","mor":"Hotel/DMC direct or Fora","tier":"luxury"},{"name":"La Hacienda Bahia Paracas","why_ultra":"Bay-edge premier resort — gardens, pool, near-inclusive feel, world-class on-site museum","earning":"Hotel commission via Fora/OutsideAgents","virtuoso_value_add":"Amenity/credit perks + pre-arranged Ballestas/reserve","mor":"Hotel/DMC direct or Fora","tier":"premier"},{"name":"Hotel Vinas Queirolo (Ica)","why_ultra":"First/only hotel inside a working ~700-ha vineyard in Peru — pisco/wine tastings, three pools, vineyard views","earning":"Hotel commission via Fora/OutsideAgents","virtuoso_value_add":"Pre-loaded wine/pisco tastings + vineyard experiences; romantic-getaway framing","mor":"Hotel/DMC direct or Fora","tier":"premier–luxury"}],"source_verified":"2026-07-07","hero":{"query":"Paracas, Nazca & the South Coast, Peru"},"geo":{"lat":-13.86,"lng":-76.2517}}'::jsonb, 78),
  ('peninsula-valdes-argentina', '10S', 'Península Valdés & Puerto Madryn, Argentina', 'Argentina', 'Patagonian steppe thrust into the Atlantic **TravelWell', 'live', 'verified', 'mountainValley', 'Patagonia & The Lakes', '{"expedition","romance","liveaboard","wildlife"}', '{}', '{"essential","comfort","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","advisory_level":"L1","advisory_updated":"2026-05-20","advisory_source":"https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories/argentina-travel-advisory.html","regional_caveat":"Rosario L2 (~1,300 km away, not this destination)","book_enabled":true,"bin":"freely bookable (L1)","consent_flow":false,"air_access_verified":true,"air_access":"PMY (Puerto Madryn / El Tehuelche) & REL (Trelew) via Buenos Aires AEP on Aerolíneas Argentinas / Flybondi / JetSMART","remote_flag":true,"water_potable":true,"notes":["cold-water no-fly diving","wind/exposure on steppe","gravel-road self-drive on peninsula","trauma evac to Buenos Aires"]},"timing":{"governed_by":"wildlife_seasonality","windows":{"southern_right_whales":{"range":"Jun–mid-Dec","peak":"Sep–Oct","where":"Puerto Pirámides"},"orca_beaching_attack":{"range":"Mar–Apr (primary) + some Oct–Nov","peak":"end-Mar–early-Apr","where":"Punta Norte"},"magellanic_penguins":{"range":"Sep–Mar","peak":"Oct–Nov","where":"Punta Tombo"},"elephant_seals":{"range":"Aug–Nov combat; pupping mid-Dec–Feb","peak":"Sep–Nov","where":"Caleta Valdés"}},"peak":"whale season Sep–Oct (broad-overlap sweet spot)","inflection":["late-Feb–early-Apr (orca chasers)","Nov (whale taper + penguin chicks + warm dive water)"],"fire_date":"curve-start minus 1–2 weeks — whale inventory mid-to-late May; orca packages late Feb; penguin day-trips late Aug","off_season_fill":"May (pre-whale calm) and Dec–Feb (penguin chicks + warmest diving + elephant-seal pupping)"},"jewels":[{"name":"Puerto Pirámides whale-watch (Southern right whales)","si_tag":"expedition","window":"Jun–mid-Dec, peak Sep–Oct","tier":"comfort","commission_path":"activity / DMC bundle","source":"https://www.puertopiramides.gov.ar/whales-season/","hook":"The signature. Boats from the only nautically-authorized whale port in Argentina; forty-tonne females with calves feet from the hull","si":"expedition","blurb":"The signature. Boats from the only nautically-authorized whale port in Argentina; forty-tonne females with calves feet from the hull","commission":"activity / DMC bundle"},{"name":"Punta Norte orca beaching-attack","si_tag":"expedition","window":"Mar–Apr (never guaranteed)","tier":"comfort","commission_path":"DMC / specialist wildlife operator","source":"https://peninsulavaldes.com/wildlife/orcas","hook":"Cliff-top watch for orcas deliberately stranding to take sea-lion pups — one of the rarest predatory spectacles on the planet","si":"expedition","blurb":"Cliff-top watch for orcas deliberately stranding to take sea-lion pups — one of the rarest predatory spectacles on the planet","commission":"DMC / specialist wildlife operator"},{"name":"Caleta Valdés elephant seals","si_tag":"expedition","window":"Aug–Nov combat; pupping Dec–Feb","tier":"comfort","commission_path":"DMC circuit / activity","source":"https://peninsulavaldes.com/wildlife/sea-elephant","si":"expedition","commission":"DMC circuit / activity"},{"name":"Punta Tombo Magellanic penguins","si_tag":"expedition","window":"Sep–Mar, chicks Oct–Nov","tier":"comfort","commission_path":"DMC day-trip / activity","source":"https://www.interpatagonia.com/puertomadryn/penguins-punta-tombo.html","si":"expedition","commission":"DMC day-trip / activity"},{"name":"Puerto Madryn sea-lion dive (Punta Loma)","si_tag":"Dive/OCA","window":"year-round; best Sep–Oct water","tier":"comfort","commission_path":"dive-operator activity","source":"https://www.civitatis.com/en/puerto-madryn/sea-lion-dive/","hook":"Dive among wild sea lions — a top-handful global experience","si":"Dive/OCA","blurb":"Dive among wild sea lions — a top-h