  ('placencia-belize', '10S', 'Placencia', 'Belize', 'Whale sharks and mainland sand **TravelWell', 'live', 'verified', 'oceanAerial', 'Belize', '{"liveaboard","expedition","diveglobal","ocean","wildlife","culture"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":["Placencia is Belize''s southern beach peninsula with the country''s best mainland beaches and its main resort/romance-wedding coast.","Gladden Spit, off Placencia, is the world''s most predictable whale-shark aggregation, timed to the Mar-Jun full moons (peak Apr-May).","The southern barrier reef (Silk Cayes, Laughing Bird Caye NP, South Water Caye) launches from Placencia; the outer atolls are reachable.","Monkey River (howler monkeys, manatees) and the Cockscomb Basin (world''s first jaguar preserve) are easy day trips.","Access is BZE -> PLJ (Placencia airstrip) by 20-30 min puddle-jumper on Tropic Air / Maya Island Air; ~3.5-4 hr drive alternative."],"safety":{"emergency":"911 (Belize national; verify on arrival)","hyperbaric_chamber":"Nearest chambers on Ambergris Caye (San Pedro): SSS Network 24/7 226-2851; Belize Chamber Project 24/7 226-2660 — DISTANCE FLAG from southern reef, plan conservative profiles","hospital":"No peninsula trauma center; Placencia/Dangriga clinics stabilize; serious trauma evacuates to Belize City","book_enabled":true,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"l3_disclosure":true,"advisory_reissued":"2026-06-18","advisory_codes":"C (Crime) only","state_dept_carveout":"only Southside Belize City restricted; Placencia open","stay_in_zone":true,"air_access_verified":"BZE -> PLJ (Placencia) by puddle-jumper (Tropic Air / Maya Island Air), 20-30 min","water":"bottled / purified only","dengue":"endemic seasonal mosquito-borne risk; repellent advised","malaria":"low/localized rural risk; negligible in tourist zone"},"timing":{"peak":"late-Dec-Apr (dry season; highest rates, biggest crowds)","whale_shark_event_peak":"Apr-May around the full moons (distinct, separate peak); 2026 full moons Mar 14 / Apr 13 / May 12 / Jun 11; windows Mar 12-24, Apr 11-23, May 10-22, Jun 9-21","shoulder_green":"Sep-Nov (green season; better value, hurricane exposure Jun-Nov)","events":"Placencia Lobsterfest ~late June (confirm 2026 date)","booking_window_lead_time":"whale-shark Apr/May 3-4 months; dry-season peak 3-4 months; shoulder 4-6 weeks","fill_the_beds":"green season lead with Monkey River, Cockscomb jaguar preserve, Hopkins Garifuna, reef days, year-round flats fly-fishing","campaign_start_trigger":"whale-shark push fires early-mid Feb 2026; dry-season peak fires late-Sep/Oct 2025; green-season value fires Jun-Jul","fire_date":"2026-02-10"},"jewels":[{"name":"Gladden Spit whale sharks (Apr-May full moons)","si_tag":"Dive Liveaboards","status":"live","tier":"premier","hook":"Snorkel or dive the world''s most predictable whale-shark aggregation, 90 min offshore.","bookable_category":"licensed whale-shark dive/snorkel","commission_path":"dive-operator direct — David''s CLIA lane, affiliate -> commissioned-agent 12-18%; reserve fee pass-through","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","si":"liveaboard","blurb":"Snorkel or dive the world''s most predictable whale-shark aggregation, 90 min offshore.","commission":"dive-operator direct — David''s CLIA lane, affiliate -> commissioned-agent 12-18%; reserve fee pass-through"},{"name":"Silk Cayes snorkel / dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Postcard barrier-reef cayes with turtles, sharks, rays and eels.","bookable_category":"reef snorkel/dive day","commission_path":"dive-operator direct / affiliate; reserve fee pass-through","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","si":"diveglobal","blurb":"Postcard barrier-reef cayes with turtles, sharks, rays and eels.","commission":"dive-operator direct / affiliate; reserve fee pass-through"},{"name":"Laughing Bird Caye National Park","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Tiny faro-reef caye 11 nm east; easy family snorkel/dive.","bookable_category":"reef day-trip","commission_path":"affiliate 4-8% / operator direct; park fee pass-through","source":"https://splashbelize.com/belize-scuba-diving-sites/whale-sharks-at-gladden-spit/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Tiny faro-reef caye 11 nm east; easy family snorkel/dive.","when":"late-Dec-Apr","commission":"affiliate 4-8% / operator direct; park fee pass-through"},{"name":"Monkey River howler-monkey + manatee watch","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Boat + river cruise + jungle hike into howler habitat; manatees on the return.","bookable_category":"guided river/wildlife tour","commission_path":"DMC (Barefoot) AOR / affiliate; village fee pass-through","source":"https://blueturtleplacencia.com/placencia-adventure-tours/monkey-river-tour","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Boat + river cruise + jungle hike into howler habitat; manatees on the return.","when":"late-Dec-Apr","commission":"DMC (Barefoot) AOR / affiliate; village fee pass-through"},{"name":"Cockscomb Basin jaguar-preserve day trip","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"World''s first jaguar reserve — 128,000 acres of trails, waterfalls, birds.","bookable_category":"guided day trip","commission_path":"DMC AOR / affiliate; sanctuary entry pass-through","source":"https://en.wikipedia.org/wiki/Cockscomb_Basin_Wildlife_Sanctuary","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","blurb":"World''s first jaguar reserve — 128,000 acres of trails, waterfalls, birds.","when":"late-Dec-Apr","commission":"DMC AOR / affiliate; sanctuary entry pass-through"},{"name":"Garifuna Coast — Hopkins day trip","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Drumming, culture and beaches of the Garifuna village of Hopkins.","bookable_category":"cultural day trip","commission_path":"DMC AOR / affiliate","source":"https://www.hamanasi.com/belize-vacation/cockscomb-jaguar-preserve-tour/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Drumming, culture and beaches of the Garifuna village of Hopkins.","when":"late-Dec-Apr","commission":"DMC AOR / affiliate"},{"name":"Flats fly-fishing (permit / bonefish / tarpon)","si_tag":"Ocean Adventures","status":"future","tier":"premier","hook":"World-class permit water on the southern flats, year-round.","bookable_category":"guided fly-fishing","commission_path":"fishing-lodge/guide direct; affiliate on packaged trips","source":"https://www.jmbelizetravel.com/placencia-sea-tours/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"World-class permit water on the southern flats, year-round.","when":"late-Dec-Apr","commission":"fishing-lodge/guide direct; affiliate on packaged trips"},{"name":"Placencia sidewalk + fishing village","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The famous narrow sidewalk, seafood shacks and end-of-peninsula soul.","bookable_category":"self-guided","commission_path":"none (drives F&B + lodging attach)","source":"https://chabilmarvillas.com/","timing":"late-Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"The famous narrow sidewalk, seafood shacks and end-of-peninsula soul.","when":"late-Dec-Apr","commission":"none (drives F&B + lodging attach)"}],"faq":[{"q":"Is Placencia good for a honeymoon or wedding?","a":"Yes — it is Belize''s most credible mainland resort/romance market, with real luxury-to-ultra range. Naïa Resort & Spa (39 beach houses + treetop villas on 224 private acres, mile of beach, from ~US$380/night) and SLH-member Itz''ana anchor the beachfront, plus true private-island elopements offshore. The peninsula earns both the wedding and the dive log.","source":"naiaresortandspa.com, 2026-07-06","si_tag":"romance"},{"q":"When can you swim with whale sharks in Placencia?","a":"Around the Mar–Jun full moons at Gladden Spit — the one place on the planet where whale-shark arrival is \"reasonably predictable.\" 2026 full moons are Mar 14, Apr 13, May 12 and Jun 11, with windows ~2 days before to ~10 days after; April and May fill first, so serious divers book three to four months ahead. Encounters are not guaranteed — you''re buying the window.","source":"splashbelize.com, 2026-07-06","si_tag":"liveaboard"},{"q":"What wildlife can you see near Placencia?","a":"Two flagship day trips. The Monkey River eco-tour (a ~45-min coastal boat run then a river cruise) carries you into black-howler-monkey habitat with crocodiles, iguanas, toucans and manatees on the return; and the Cockscomb Basin — the world''s first jaguar preserve, 128,000 acres, est. 1986 — is a half-day inland via Maya Center.","source":"blueturtleplacencia.com, 2026-07-06","si_tag":"expedition"},{"q":"Does Placencia have good beaches and reef?","a":"Yes — the country''s best mainland beaches on a 16-mile peninsula, plus the closest mainland launch to the southern reef. Splash Dive Center''s home waters — the Silk Cayes, South Water Caye and Laughing Bird Caye — are \"postcard perfect islands on the barrier reef\" with turtles, sharks, rays and eels, most a 30–60 minute run out.","source":"splashbelize.com, 2026-07-06","si_tag":"tropical"},{"q":"Can you fly-fish the flats in Placencia?","a":"Yes — the southern flats and river mouths are world-class permit water, fishable year-round for permit, bonefish and tarpon by skiff. It''s a high-value niche booked through Placencia fishing lodges and guides, and a reliable green-season lever when the reef days are between fronts.","source":"jmbelizetravel.com, 2026-07-06","si_tag":"ocean"},{"q":"Is there a destination spa / wellness stay in Placencia?","a":"Yes — Naïa Resort & Spa is built for it: a 224-acre private property with a mile of beach, a destination spa and a private-island couples retreat, strong on both romance and wellness. It''s the anchor for a quiet-beach reset paired with reef or river days.","source":"naiaresortandspa.com, 2026-07-06","si_tag":"wellness"},{"q":"Is Placencia safe right now?","a":"Yes, with the standard disclosure. Belize is at US State Dept Level 3 (reissued June 18, 2026, code C/Crime only), but the advisory names only Southside Belize City for reconsideration — Placencia is not named anywhere. Access is BZE → PLJ by puddle-jumper, so travelers stay in-zone and never route through the named district.","source":"travel.state.gov, 2026-06-18","si_tag":"safety"},{"q":"What''s the real risk to plan for in Placencia?","a":"Dive-chamber distance and open-water boat runs, not crime. The nearest recompression chamber is on Ambergris Caye (San Pedro), a meaningful distance north of the southern reef, so plan conservative profiles and no-fly windows; the run to Gladden Spit is ~90 minutes each way with early 6–7am departures. There is no full trauma center on the peninsula — serious cases evacuate to Belize City.","source":"ambergriscaye.com, 2026-07-06","si_tag":"safety"},{"q":"Is swimming with whale sharks dangerous?","a":"It runs guided-only with a permitted operator — Gladden Spit is inside a marine reserve and only permitted operators may run the aggregation, no-touch and no-chase. Snorkelers work the surface aggregation over 2–3 hours (moderate swimming ability needed); divers descend to ~50–80 ft to meet the sharks and must be certified and guided.","source":"flowersvacationrentals.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Placencia, Belize Travel Guide 2026 — Whale Sharks, Beaches & Reef | TravelWell.World","meta_description":"Plan Placencia: the Gladden Spit whale-shark season (Apr-May full moons), Silk Cayes & Monkey River, best mainland beaches, luxury & private-island resorts, straight L3 safety and dive-chamber facts.","slug":"placencia-belize","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"en","primary_keywords":["Placencia Belize travel guide","whale sharks Placencia","Placencia beaches"],"local_keywords":["tiburon ballena Placencia Belice","temporada tiburon ballena Gladden Spit 2026","playas de Placencia","tour Monkey River Placencia","buceo Silk Cayes Placencia","resorts de lujo Placencia"],"hreflang":["en","es"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"liveaboard","status":"live"},{"si":"expedition","status":"live"},{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Itz''ana Resort & Residences","price_tier":"ultra","virtuoso":true,"earning":"on application / host-Virtuoso / SLH trade / Fora","mor_posture":true,"note":"beachfront + marina, Small Luxury Hotels of the World","source":"https://slh.com/hotels/itz''ana-resort-and-residences"},{"name":"Naia Resort & Spa","price_tier":"luxury","virtuoso":true,"earning":"host-agency / Virtuoso AOR","mor_posture":true,"note":"224-acre, mile of beach, destination spa; R&H + Wellness","source":"https://www.naiaresortandspa.com/"},{"name":"Turtle Inn (Coppola Hideaways)","price_tier":"ultra","virtuoso":true,"earning":"Coppola Hideaways trade / host-Virtuoso / Fora","mor_posture":true,"note":"Balinese-inspired thatched beach hideaway near village","source":"https://thecoppolahideaways.com/resort/turtle-inn"},{"name":"Gladden Private Island","price_tier":"ultra","virtuoso":false,"earning":"on application / host-Virtuoso / private-island trade","mor_posture":true,"note":"single-villa caye, helicopter transfer on 7+ nights, whale sharks off-island","source":"https://www.privateislandsonline.com/central-america/belize/gladden-private-island"},{"name":"Ray Caye Island Resort","price_tier":"ultra","virtuoso":false,"earning":"on application / host-Virtuoso / private-island trade","mor_posture":true,"note":"private island on edge of Gladden Spit & Silk Cayes reserves","source":"https://raycaye.com/"},{"name":"Copal Tree Lodge (Muy''Ono, Toledo)","price_tier":"luxury","virtuoso":false,"earning":"Muy''Ono trade / host-Virtuoso / Fora","mor_posture":true,"note":"rainforest all-inclusive luxury lodge near Punta Gorda","source":"https://etichotels.com/journal/top-10-sustainable-hotels-in-belize/"}],"source_verified":"2026-07-06","hero":{"query":"Placencia, Belize"},"geo":{"lat":16.5155,"lng":-88.3665}}'::jsonb, 80),
  ('playa-del-carmen-mexico', '10S', 'Playa del Carmen', 'Mexico', 'Cenotes, Fifth Avenue and the Cozumel ferry **TravelWell', 'live', 'verified', 'venice', 'Quintana Roo (Cancún & Riviera Maya)', '{"romance","expedition","diveglobal","culture"}', '{}', '{"essential","comfort","ultra"}', null, null, '{"key_facts":["Quinta Avenida (Fifth Avenue) is a multi-km pedestrian dining/shopping/nightlife street parallel to the beach.","Cozumel reef wall is a 40-minute ferry away (Xcaret Xailing/Winjet/Ultramar, ~US$32 round trip).","Cenotes Chikin-Ha, Chaak Tun and Eden are within ~30 minutes for swim/snorkel/cavern dives.","Xcaret and Xplor eco-parks (14-line, 3.8 km zipline circuit) sit just outside town.","Best weather is November–March; May–October is hot, humid and rainy."],"safety":{"emergency":"911","hospital":"Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200); serious trauma escalates to Cancún","advisory_level":"L2","malaria":"none in tourist Quintana Roo","yellow_fever":"none required"},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest)","sargassum_window":"Apr-Aug (Jun-Jul peak); Playa moderate risk with barrier program","booking_window_lead_time":"peak 3-4 months; shoulder 4-6 months","holiday_event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"fill_the_beds":"green/sargassum months pivot to cenote dives, Cozumel reef, Xcaret/Xplor parks, Fifth Avenue food+nightlife","campaign_start_trigger":"peak campaigns open Aug-Sep; shoulder ~3-4 months out"},"jewels":[{"name":"Cozumel reef wall (Palancar/Santa Rosa/Columbia)","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"World-class drift-wall diving on the Mesoamerican Reef, 40 min by ferry.","bookable_category":"dive excursion / liveaboard","commission_path":"Amstar excursion 12% or dive-operator affiliate","source":"https://www.viator.com/Playa-del-Carmen/Cozumel/day-trips-d5501-d632","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"World-class drift-wall diving on the Mesoamerican Reef, 40 min by ferry.","when":"Dec-Apr","commission":"Amstar excursion 12% or dive-operator affiliate"},{"name":"Cenote cavern dive — Chikin-Ha / Dos Ojos","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Guided cavern dives with light beams and stalactites in the world''s longest cave system.","bookable_category":"cenote cavern dive (guide required)","commission_path":"DMC excursion 12% / affiliate 4-8%","source":"https://www.tripadvisor.com/Attractions-g150812-Activities-Playa_del_Carmen_Yucatan_Peninsula.html","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Guided cavern dives with light beams and stalactites in the world''s longest cave system.","when":"Dec-Apr","commission":"DMC excursion 12% / affiliate 4-8%"},{"name":"Xplor zipline + underground river","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Mexico''s largest zipline circuit — 14 lines over 3.8 km plus amphibious buggies.","bookable_category":"eco-park adventure","commission_path":"Xcaret Agents / affiliate; park entry pass-through","source":"https://blog.xcaret.com/en/welcome-to-playa-del-carmen-mexico/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Mexico''s largest zipline circuit — 14 lines over 3.8 km plus amphibious buggies.","when":"Dec-Apr","commission":"Xcaret Agents / affiliate; park entry pass-through"},{"name":"Cobá + Tulum ruins day loop","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Cliff-top Tulum plus bikeable jungle pyramids at Cobá in one Maya day.","bookable_category":"guided cultural excursion","commission_path":"Amstar 12%; ruin entry pass-through","source":"https://www.amstardmc.com/en/destinations/mexico/tulum/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Cliff-top Tulum plus bikeable jungle pyramids at Cobá in one Maya day.","when":"year-round","commission":"Amstar 12%; ruin entry pass-through"},{"name":"La Casa de la Playa (Grupo Xcaret)","si_tag":"Romance & Honeymoons","status":"live","tier":"ultra","hook":"AAA Five-Diamond luxury on the Xcaret estate with private park access.","bookable_category":"luxury all-inclusive resort","commission_path":"Xcaret Agents Pro — 15% auto-paid at check-out","source":"https://www.travelagentcentral.com/your-business/grupo-xcaret-launches-xcaret-agents-pro-booking-tool","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"AAA Five-Diamond luxury on the Xcaret estate with private park access.","when":"Dec-Apr","commission":"Xcaret Agents Pro — 15% auto-paid at check-out"}],"faq":[{"q":"Is Playa del Carmen safe to visit right now?","a":"Yes — freely bookable, no hold. Playa sits in Quintana Roo, which carries a standard US State Dept Level 2 \"Exercise Increased Caution\" (dated 2026-05-29) for crime. It is a busy, walkable tourist town; stay in well-lit zones after dark, and note the 24-hour Hospiten Riviera Maya ER is in town for medical needs.","source":"travel.state.gov, 2026-07-04","si_tag":"safety"},{"q":"What''s the real risk to plan for in Playa del Carmen?","a":"Sargassum, weather and water — not violent crime against tourists. 2026 is a record-forecast sargassum year, but Playa is moderate risk thanks to active municipal cleanup and a 5-km double-barrier program, with landings in pulses. Drink bottled water, use repellent for dengue (peak May–Nov, no malaria), and note hurricane season runs June–November.","source":"deeparrival.com / cdc.gov, 2026-07-04","si_tag":"safety"},{"q":"Is cenote cavern diving safe here?","a":"Yes, with a certified guide — this is an overhead environment, not open water. Cenote cavern dives (Chikin-Ha, Dos Ojos) require a certified cave/cavern guide and stay in the daylight zone; never enter the dark cave zone without full cave certification. Observe no-fly of 18h single / 24h repetitive before any Cancún/Cozumel flight home; a recompression chamber is in town.","source":"sssnetwork.com / tripadvisor.com, 2026-07-04","si_tag":"safety"},{"q":"Can I dive Cozumel and the cenotes from Playa del Carmen?","a":"Yes — Playa is the best mainland dive base for both. Cozumel''s drift-wall reef (Palancar, Santa Rosa, Columbia) is a 40-minute ferry away at ~US$32 round trip, and cenote cavern dives sit under 30 minutes inland. Cozumel walls are drift dives for a reputable operator; cenotes are guide-required and weather-independent.","source":"viator.com / tripadvisor.com, 2026-07-04","si_tag":"diveglobal"},{"q":"What is there to do on Fifth Avenue?","a":"Fifth Avenue (Quinta Avenida) is the Riviera Maya''s densest dining and nightlife strip — a multi-kilometre pedestrian street of tacos-to-rooftop bars parallel to the sand. It is the town''s social spine, best on a weekday evening before the crowds; guided food-and-rooftop crawls are the easy way to graze it.","source":"tripadvisor.com, 2026-07-04","si_tag":"nightlife"},{"q":"Are the Xcaret and Xplor parks worth it, especially for families?","a":"Yes — they are the region''s marquee eco-parks. Xcaret runs cenotes, underground rivers and Maya performances; Xplor has Mexico''s largest zipline circuit (14 lines over 3.8 km) plus amphibious buggies. Park admission (~US$85–110 at Xcaret) is pass-through, and both sit just outside town — a full family day out.","source":"blog.xcaret.com, 2026-07-04","si_tag":"expedition"},{"q":"Can I visit Maya ruins from Playa del Carmen?","a":"Yes — it is the corridor''s best ruins base. Tulum''s cliff-top ruins and Cobá''s bikeable jungle pyramids pair in one day loop, and Chichén Itzá is a longer day trip; early morning (Nov/Feb) is best. Amstar and other DMCs run guided excursions, with ruin entry as a pass-through cost.","source":"amstardmc.com, 2026-07-04","si_tag":"culture"},{"q":"Where''s the best luxury for a honeymoon near Playa del Carmen?","a":"The Mayakoba estate and La Casa de la Playa. Mayakoba (Rosewood, Banyan Tree, Andaz) is a gated 595-acre lagoon estate of Virtuoso-affiliated flagships; La Casa de la Playa (Grupo Xcaret) is a 63-suite AAA Five-Diamond boutique ranked #1 Resort in Mexico for 2025. Both are ultra-tier honeymoon addresses on Playa''s doorstep.","source":"jetsetchristina.com / virtuoso.com, 2026-07-04","si_tag":"romance"},{"q":"When is the best time to visit Playa del Carmen?","a":"November–March is the dry, cooler high season (best weather, highest rates); May–October is hot, humid and rainy at the cheapest rates. The value sweet spots are the May–June and November shoulders at ~30–40% off, with November landing clear of sargassum and ahead of the holiday surge.","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Playa del Carmen Travel Guide 2026 — Cenotes, Cozumel Diving & Fifth Avenue | TravelWell.World","meta_description":"Plan Playa del Carmen: cenote diving, the 40-minute Cozumel reef ferry, Fifth Avenue nightlife, Xcaret parks, plus straight 2026 sargassum, Level 2 safety and dive-chamber info.","slug":"playa-del-carmen-mexico","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["qué hacer en Playa del Carmen","cenotes cerca de Playa del Carmen","ferry a Cozumel desde Playa del Carmen","mejor época para visitar Playa del Carmen 2026","sargazo Playa del Carmen 2026","buceo en cenotes Playa del Carmen","Quinta Avenida Playa del Carmen"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"expedition","status":"live"},{"si":"diveglobal","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Rosewood Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Andaz / Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Fairmont Mayakoba","price_tier":"luxury","virtuoso":false,"earning":"on application / host AOR","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Playa del Carmen, Mexico"},"geo":{"lat":20.6296,"lng":-87.0739}}'::jsonb, 81),
