ce","si_tag":"CLT","tier":"essential","commission_path":"cultural-tour operator package (Elementos/Zenit)","source":"https://www.elementos-chile.com/en/tour/cultours/cultour-mapuche-ruka","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Hosted by Araucanía families — enter the ruka, hear the cosmology and the meaning of the flag and spiritual structure","si":"culture","blurb":"Hosted by Araucanía families — enter the ruka, hear the cosmology and the meaning of the flag and spiritual structure","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"cultural-tour operator package (Elementos/Zenit)"},{"name":"Ojos del Caburgua turquoise pools + falls","si_tag":"expedition","tier":"essential","commission_path":"half-day tour/transfer commissionable; site free/low-fee","source":"https://www.visitchile.com/en/ojos-del-caburgua/","timing":"[''Dec'', ''Jan'', ''Feb'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"[''Dec'', ''Jan'', ''Feb'']","commission":"half-day tour/transfer commissionable; site free/low-fee"}],"faq":null,"seo":{"meta_title":"Pucón, Chile Travel Guide — Villarrica Volcano, Hot Springs & Lake District Adventure | TravelWell","search_language":"es-CL","local_keywords":["qué hacer en Pucón","volcán Villarrica ascenso","Termas Geométricas","Parque Nacional Huerquehue","rafting río Trancura","termas cerca de Pucón","Ojos del Caburgua","experiencia mapuche ruka","cuándo ir a Pucón","Pucón es seguro"],"hreflang":["en","es-CL"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07"},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Hotel Antumalal","tier":"ULTRA/icon","earning":"consortia-commissionable (Virtuoso/Fora potential) + direct","note":"1950 Bauhaus icon on Lake Villarrica; 16 rooms + 3 chalets + Lake House; Pollak family-owned"},{"name":"andBeyond Vira Vira","tier":"ULTRA","earning":"andBeyond/consortia-commissionable + all-in MoR potential","note":"55-acre organic hacienda on the Liucura River; 6 lodge suites + 12 villa suites; guided-adventure inclusive"},{"name":"AWA / Puerto Varas ultra corridor (cross-ref)","tier":"ULTRA (cross-ref)","earning":"consortia + multi-property MoR","note":"two-lake/two-volcano ultra string pairing Pucón with Puerto Varas/Llanquihue"}],"source_verified":null,"hero":{"query":"Pucón & the Araucanía Lakes, Chile, Chile"},"geo":{"lat":-39.282,"lng":-71.955}}'::jsonb, 82),
  ('puerto-aventuras-mexico', '10S', 'Puerto Aventuras', 'Mexico', 'Gated marina, reef off the beach **TravelWell', 'live', 'verified', 'venice', 'Quintana Roo (Cancún & Riviera Maya)', '{"romance","diveglobal","ocean","wildlife"}', '{}', '{"comfort","premier"}', null, null, '{"key_facts":["One of the few mainland deep-water marinas between Cancún and Belize City — a safe-haven harbor.","The reef sits ~100 feet from shore, allowing several dives per day with minimal transit.","Gated community with controlled access and 24/7 security — among the safest areas in the Riviera Maya.","Adjacent Dolphin Discovery offers swims with dolphins, sea lions and manatees.","Cenote Azul (between Puerto Aventuras and Playa del Carmen) makes it an easy cenote-dive base."],"safety":{"emergency":"911","hospital":"Nearest trauma: Hospiten Riviera Maya, Playa del Carmen (+52 984 159 2200), ~20 km north; local clinics stabilize/transfer; major trauma to Cancún","advisory_level":"L2","malaria":"none in tourist Quintana Roo","yellow_fever":"none required"},"timing":{"peak":"Dec-Apr (dry season; highest rates, biggest crowds)","shoulder":"May-Jun & Nov (~30-40% off, good weather)","green":"Jun-mid-Oct (hurricane/low; cheapest; marina monitors weather)","marina_sportfishing_calendar":"charters year-round weather-permitting; peak billfish/dorado spring dry window (Mar-Jun sailfish/mahi); confirm species per season with operator","sargassum_window":"Apr-Aug (Jun-Jul peak); marina/inlet + dive focus softens beach dependence","booking_window_lead_time":"peak 3-4 months (gated villa/condo stock finite, book earlier); shoulder 4-6 months","holiday_event_peaks":["Christmas/New Year","Spring Break (Mar)","Semana Santa"],"fill_the_beds":"sargassum/green months lead with near-shore reef dives, Cenote Azul, Dolphin Discovery, sportfishing charters, marina promenade","campaign_start_trigger":"peak campaigns open Aug-Sep; shoulder ~3-4 months out; spring-sportfishing / dive-base push through sargassum months"},"jewels":[{"name":"Deep-water marina sportfishing charter","si_tag":"Ocean Adventures","status":"future","tier":"premier","hook":"Half/full-day offshore charters from a rare mainland deep-water safe-haven harbor.","bookable_category":"fishing charter","commission_path":"affiliate 4-8% / DMC 12%; berth fees pass-through","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Half/full-day offshore charters from a rare mainland deep-water safe-haven harbor.","when":"Dec-Apr","commission":"affiliate 4-8% / DMC 12%; berth fees pass-through"},{"name":"Dolphin Discovery swim","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Sea-inlet swims with dolphins, sea lions and manatees beside the marina.","bookable_category":"marine wildlife experience","commission_path":"brand affiliate; park entry pass-through","source":"https://www.dolphindiscovery.com/riviera-maya/riviera-maya.asp","si":"wildlife","blurb":"Sea-inlet swims with dolphins, sea lions and manatees beside the marina.","commission":"brand affiliate; park entry pass-through"},{"name":"Shore-adjacent reef dive (reef ~100 ft out)","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Near-shore reef dives with minimal transit — several dives in a day.","bookable_category":"reef dive","commission_path":"dive-operator affiliate / DMC 12%","source":"https://www.prodiveinternational.com/diving/mexico/puerto-aventuras/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Near-shore reef dives with minimal transit — several dives in a day.","when":"Dec-Apr","commission":"dive-operator affiliate / DMC 12%"},{"name":"Cenote Azul cavern dive/snorkel","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Popular cenote between Puerto Aventuras and Playa — cave country from a marina base.","bookable_category":"cenote cavern dive (guide required)","commission_path":"DMC 12% / affiliate 4-8%; entry pass-through","source":"https://alohawanderers.com/puerto-aventuras-what-to-know-before-visiting-this-riviera-maya-gem/","si":"diveglobal","blurb":"Popular cenote between Puerto Aventuras and Playa — cave country from a marina base.","commission":"DMC 12% / affiliate 4-8%; entry pass-through"},{"name":"Dreams Aventuras Riviera Maya","si_tag":"Romance & Honeymoons","status":"live","tier":"premier","hook":"Secure, calm gated-community all-inclusive honeymoon base.","bookable_category":"all-inclusive resort","commission_path":"all-inclusive AOR ~12%","source":"https://www.trivago.com/en-US/oar/resort-dreams-aventuras-riviera-maya-puerto-aventuras","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Secure, calm gated-community all-inclusive honeymoon base.","when":"Dec-Apr","commission":"all-inclusive AOR ~12%"}],"faq":[{"q":"Is Puerto Aventuras safe to visit right now?","a":"Yes — freely bookable, and unusually calm. It sits in Quintana Roo, which carries a standard US State Dept Level 2 \"Exercise Increased Caution\" (dated 2026-05-29), but Puerto Aventuras is a gated, master-planned community with controlled access and 24/7 security — one of the safest-feeling areas in the Riviera Maya. Nearest full trauma is Hospiten in Playa del Carmen, ~20 min north.","source":"travel.state.gov / alohawanderers.com, 2026-07-04","si_tag":"safety"},{"q":"What''s the real risk to plan for in Puerto Aventuras?","a":"Water, mosquitoes, hurricanes and sargassum — not crime. Drink bottled/purified water, use repellent for dengue (peak May–November, no malaria in tourist Quintana Roo), and note hurricane season runs June–November. Sargassum is heavy region-wide in 2026 (Apr–Aug), but the marina and dive focus soften the beach hit here.","source":"cdc.gov / deeparrival.com, 2026-07-04","si_tag":"safety"},{"q":"Is the diving and cenote diving here safe for beginners?","a":"Yes — the near-shore reef is beginner-friendly, but cenotes have rules. The reef ~100 ft out means calm, short-transit dives; cenote cavern diving, however, requires a certified cave/cavern guide and stays in the daylight zone (no cave-zone penetration without full cave certification). Observe no-fly of 18h single / 24h repetitive; the nearest chamber is ~20 min north in Playa del Carmen.","source":"prodiveinternational.com / sssnetwork.com, 2026-07-04","si_tag":"safety"},{"q":"What is the marina and sportfishing like in Puerto Aventuras?","a":"It is one of the few mainland deep-water marinas between Cancún and Belize City — a secure safe-haven harbor for yachts, sailors and sportfishers. Offshore charters run year-round (weather permitting), with the peak billfish and mahi window in the Mar–Jun spring dry season; berth fees are pass-through and the guided charter is the commissionable wrapper.","source":"alohawanderers.com, 2026-07-04","si_tag":"ocean"},{"q":"Is Puerto Aventuras a good dive base?","a":"Yes — it is a genuine near-shore reef and cenote base. The reef is only ~100 feet from the beach, so you can log several dives a day with minimal boat transit, and Cenote Azul (between Puerto Aventuras and Playa del Carmen) puts cave country within easy reach. Best reef visibility runs Nov–May.","source":"prodiveinternational.com / alohawanderers.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Is Puerto Aventuras good for families?","a":"Very — it is built for calm, safe family days. The adjacent Dolphin Discovery center offers sea-inlet swims with bottlenose dolphins, sea lions and manatees; add the gated 24/7-security layout, a calm marina promenade and near-shore reef, and it suits families and multigenerational groups well.","source":"dolphindiscovery.com, 2026-07-04","si_tag":"family"},{"q":"Is Puerto Aventuras good for a honeymoon?","a":"Yes, for couples who want secure and quiet over party energy. The in-community options are the branded all-inclusive Dreams Aventuras and private gated marina/golf villas with chef and concierge; the wider luxury tier runs ~US$400–600+/night in March. For branded ultra, Mayakoba (Rosewood, Banyan Tree) is ~30–40 min north with an easy marina/dive day trip.","source":"machupicchu.org / trivago.com, 2026-07-04","si_tag":"romance"},{"q":"Can I do Maya ruins from Puerto Aventuras?","a":"Yes — Tulum and Cobá are easy guided day trips, alongside Akumal''s turtle bay ~10 min south. Amstar and other Riviera Maya DMCs run cenote, Tulum-ruins and Akumal-turtle excursions from Puerto Aventuras; entries are pass-through, with the guided excursion the commissionable wrapper.","source":"embracethejourneytravel.com, 2026-07-04","si_tag":"culture"},{"q":"When is the best time to visit Puerto Aventuras?","a":"December–April is peak (best weather, highest rates); the value windows are the May–June and November shoulders at ~30–40% off, with November clear of sargassum. The green season (Jun–mid-Oct) is hot, rainy and cheapest with hurricane exposure — but the marina and dive product hold up better than a pure beach stay.","source":"machupicchu.org / travelswithelle.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Puerto Aventuras Travel Guide 2026 — Marina, Reef Diving & Dolphins | TravelWell.World","meta_description":"Plan Puerto Aventuras: a gated deep-water marina town with reef 100 ft from shore, cenote diving, dolphin swims and sportfishing, plus 2026 sargassum, Level 2 safety and dive-chamber info.","slug":"puerto-aventuras-mexico","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04","search_language":["en","es-MX"],"local_keywords":["qué hacer en Puerto Aventuras","marina Puerto Aventuras","buceo en Puerto Aventuras","Dolphin Discovery Puerto Aventuras","pesca deportiva Puerto Aventuras","villas en Puerto Aventuras","Cenote Azul Puerto Aventuras","es seguro Puerto Aventuras"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Private gated marina/golf villas","price_tier":"luxury","virtuoso":false,"earning":"on application / host or luxury-DMC villa AOR","mor_posture":true,"note":"top of in-community ladder; no true ultra hotel in-community","source":"https://www.rentalescapes.com/rentals/luxury-vacation-rentals-mexico/riviera-maya/puerto-aventuras"},{"name":"Dreams Aventuras Riviera Maya","price_tier":"premier","virtuoso":false,"earning":"all-inclusive AOR ~12% (Hyatt Inclusive/host)","mor_posture":true,"note":"top hotel SKU in-community, not true ultra","source":"https://www.trivago.com/en-US/oar/resort-dreams-aventuras-riviera-maya-puerto-aventuras"},{"name":"Rosewood Mayakoba (~30-40 min north)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"note":"nearest true ultra hotel","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"Banyan Tree / Andaz-Alila Mayakoba","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso","mor_posture":true,"source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Puerto Aventuras, Mexico"},"geo":{"lat":20.4986,"lng":-87.2261}}'::jsonb, 83)
insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('puerto-morelos-mexico', '10S', 'Puerto Morelos', 'Mexico', '*If it''s a reef 500 meters off a sleepy', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","ocean","adventure","culinary"}', '{}', '{"essential","comfort","premier"}', null, 'core', '{"key_facts":["Puerto Morelos Reef National Park lies less than 500 m offshore, one of the best-preserved in the Caribbean","Juan Escutia boat is now an artificial reef; reef holds turtles, rays, nurse/bull sharks","Northern gateway to the ~17 km Route of the Cenotes (entry ~150-250 MXN each)","Deep-sea fishing for dorado, wahoo, tuna, barracuda","Runs ~20-30% cheaper than Playa del Carmen, 40-60% cheaper than Cancún Hotel Zone"],"safety":{"emergency":"911","hospital":"town clinics; major trauma in Cancún (~36 km, Galenia/Hospiten - verify) or Playa del Carmen; hyperbaric via SSS Cancún / Cozumel","advisory_level":"L2","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required"},"timing":{"peak":"Dec-Apr (dry/high season; driest reef water, own rates peak)","shoulder":"May-Jun & Nov (~30-40% off winter, layered on structural ~20-30% vs Playa del Carmen)","green":"Jun-mid-Oct (hurricane season, ~40-60% off; reef/cenote year-round, dry-season visibility best)","booking_lead":"shoulder/green beds 2-4 wks; reef/cenote tours 1-3 wks; Dec-Apr beds + Zoëtry/Royalton Reserve ultra suite 3-6+ months (more for Christmas/NY)","off_season_specials":"double-discount play - ''cheaper than Cancún AND low season''; pair value bed with year-round national-park reef + weather-resilient Route of the Cenotes; disclose hurricane/sargassum","event_peaks":"Christmas-New Year, US spring break (Mar); no single marquee wildlife event - reef + cenotes are the year-round draw","campaign_start":"winter/value-vs-Cancún Aug-Sep; green-season ''cheaper base + cenotes'' Apr-May; ultra corridor (Mayakoba/Zoëtry) 6-9 months ahead"},"jewels":[{"name":"Juan Escutia wreck","si_tag":"diveglobal","status":"future","tier":"comfort","hook":"sunken boat now an artificial reef and fish refuge","bookable_category":"guided reef/wreck dive","commission_path":"local dive-op → OTA affiliate","source":"https://www.kooxdiving.com/en/activities/diving-in-the-sea/puerto-morelos-reef-shipwreck-diving/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"sunken boat now an artificial reef and fish refuge","when":"Dec-Apr","commission":"local dive-op → OTA affiliate"},{"name":"Puerto Morelos Reef National Park snorkel","si_tag":"ocean","status":"future","tier":"essential","hook":"living reef under 500 m offshore, turtles/rays/lobster","bookable_category":"guided reef snorkel/dive","commission_path":"local operator → OTA (park fee pass-through)","source":"https://voyage-mexico.com/en/puerto-morelos.html","si":"ocean","blurb":"living reef under 500 m offshore, turtles/rays/lobster","commission":"local operator → OTA (park fee pass-through)"},{"name":"Deep-sea fishing charter","si_tag":"ocean","status":"future","tier":"premier","hook":"half/full-day for dorado, wahoo, tuna, barracuda","bookable_category":"private/shared charter","commission_path":"local charter operator → curated-recommend","source":"https://voyage-mexico.com/en/puerto-morelos.html","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"half/full-day for dorado, wahoo, tuna, barracuda","when":"Dec-Apr","commission":"local charter operator → curated-recommend"},{"name":"Route of the Cenotes","si_tag":"globaladv","status":"future","tier":"comfort","hook":"~17 km jungle road of open/semi-open/cave cenotes","bookable_category":"day tour + per-cenote entry","commission_path":"DMC/local operator → OTA (entry pass-through)","source":"https://snorkelingadventure.com/blog/snorkeling-puerto-morelos-cenotes-riviera-maya-adventure/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"~17 km jungle road of open/semi-open/cave cenotes","when":"Dec-Apr","commission":"DMC/local operator → OTA (entry pass-through)"},{"name":"Fishing-village seafood + craft market","si_tag":"culinary","status":"future","tier":"essential","hook":"fresh-off-the-boat ceviche + plaza craft market","bookable_category":"food/culture experience","commission_path":"curated-recommend (largely non-commissionable)","source":"https://www.palladiumhotelgroup.com/en/travel-guides/mexico/riviera-maya/what-to-see/puerto-morelos","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"fresh-off-the-boat ceviche + plaza craft market","when":"Dec-Apr","commission":"curated-recommend (largely non-commissionable)"}],"faq":[{"q":"Is Puerto Morelos safe to visit right now?","a":"Yes — freely bookable, no hold. Puerto Morelos sits in Quintana Roo, which carries a standard US State Dept Level 2 \"Exercise Increased Caution\" (dated 2026-05-29). It is a quiet, still-working fishing village; it has town clinics, with major trauma care in Cancún ~36 km north (Galenia, Hospiten) or Playa del Carmen ~40 min south.","source":"travel.state.gov","si_tag":"safety"},{"q":"What''s the real risk to plan for in Puerto Morelos?","a":"Sargassum, hurricanes and water — not crime. 2026 is heavy region-wide for sargassum, and Puerto Morelos'' open Caribbean-facing beaches are affected, so plan cenote and reef days as hedges; drink bottled water, use repellent for dengue (no malaria in the tourist zone), and note hurricane season runs June–November, September riskiest.","source":"howisthesargassum.com","si_tag":"safety"},{"q":"Is the reef and cenote diving safe here?","a":"Yes, within the rules. The national-park reef under 500 m offshore is shallow and beginner-friendly, and the Juan Escutia is a shallow wreck dive — but nurse and bull sharks are present, so no baiting and keep your distance. Cenote/cavern diving requires cave/cavern certification for overhead zones; observe no-fly of 18–24 hours, with the nearest chamber ~36 km north in Cancún.","source":"kooxdiving.com","si_tag":"safety"},{"q":"Is Puerto Morelos good for diving and the Juan Escutia wreck?","a":"Yes — it is an underrated day-boat dive base. The Puerto Morelos Reef National Park sits under 500 m offshore, one of the Caribbean''s best-preserved reefs, and the sunken Juan Escutia is now an artificial reef and fish refuge steps away. Visibility is best in the dry Oct–March window; book in town, where it is cheaper and supports local operators.","source":"voyage-mexico.com","si_tag":"diveglobal"},{"q":"Can I go deep-sea fishing from Puerto Morelos?","a":"Yes — it is a working fishing port, so charters are authentic and close at hand. Half- and full-day trips target dorado (mahi-mahi), wahoo, tuna and barracuda, with gear and guide included; the species mix is seasonal, so confirm with the operator. It pairs naturally with the fresh-off-the-boat ceviche at the beachfront cantinas.","source":"voyage-mexico.com","si_tag":"ocean"},{"q":"What is the Route of the Cenotes?","a":"A ~17 km jungle road of cenotes running inland from town — Puerto Morelos is its northern gateway. It strings together open, semi-open and cave cenotes for swimming, cavern diving and ziplining, at roughly 150–250 MXN entry each. Because they are shaded jungle sites, cenotes are weather-resilient — a strong rainy-day and green-season option.","source":"snorkelingadventure.com","si_tag":"globaladv"}],"seo":{"meta_title":"Puerto Morelos, Mexico: Reef, Cenotes & Fishing Village","meta_description":"A quiet Riviera Maya port with a national-park reef 500 m offshore, the Juan Escutia wreck, and the Route of the Cenotes. Cheaper than Cancún — when and how to book.","slug":"puerto-morelos-mexico","primary_keyword":"Puerto Morelos reef diving","long_tail":["Puerto Morelos Reef National Park","Juan Escutia wreck dive","Route of the Cenotes Puerto Morelos","Puerto Morelos fishing village","Puerto Morelos vs Cancun value"],"search_language":"es-MX (restated, not machine-translated)","local_keywords":["arrecife Puerto Morelos","Parque Nacional Arrecife de Puerto Morelos","buceo pecio Juan Escutia","Ruta de los Cenotes","pueblo pesquero Puerto Morelos","villas frente al mar Puerto Morelos","qué hacer en Puerto Morelos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":{"bin":"freely_bookable","level":"L2","codes":[],"consent_flow":false,"note":"Quintana Roo/Mexico US L2 (Exercise Increased Caution) - freely bookable; MXN currency, USD widely accepted"},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"ocean","name":"ocean","status":"future"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"culinary","name":"culinary","status":"future"}],"ultra":[{"name":"Zoëtry / Royalton Reserve Paraíso de la Bonita, a Luxury Collection Resort, Riviera Maya","why_ultra":"IN Puerto Morelos (Hwy Km 328); 90-100 ocean-front suites w/ plunge pools, 14 acres, thalasso spa, one of only 3 Luxury Collection all-inclusives worldwide, AAA Five Diamond 15 yrs (Zoëtry heritage); rebranded to Royalton Reserve adults-only, operating 2026 - verify current brand","earning":"on application / via host-Virtuoso (Marriott Luxury Collection + Royalton/Blue Diamond); verify %","virtuoso_value_add":"verify Marriott STARS/Luxury Collection amenities - not documented","mor":"commission-on-net; no net-rate resale markup","source":"https://www.tripadvisor.com/Hotel_Review-g240327-d28213141-Reviews-Royalton_Reserve_Paraiso_de_la_Bonita_a_Luxury_Collection_Resort_Riviera_Maya_Adult_A.html"},{"name":"Mayakoba enclave (Rosewood / Banyan Tree / Fairmont / Andaz) - ADJACENT, verify municipality","why_ultra":"620-acre gated ultra enclave, 4 flagship resorts; STRAIGHT GEOGRAPHY: administratively in Solidaridad (Km 298, Playa del Carmen area), NOT Puerto Morelos - do not label as in Puerto Morelos; nearest true-ultra cluster + standard corridor pull-out","earning":"on application / via host-Virtuoso (Rosewood Elite / Fairmont / Hyatt Prive / Banyan Tree); verify %","virtuoso_value_add":"Rosewood Mayakoba is Virtuoso-preferred - verify current amenity package","mor":"commission-on-net; no resale markup","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"}],"source_verified":"2026-07-04","hero":{"query":"Puerto Morelos, Mexico"},"geo":{"lat":20.8478,"lng":-86.8758}}'::jsonb, 84),
  ('puerto-vallarta-mexico', '10S', 'Puerto Vallarta', 'Mexico', 'Humpback season on Banderas Bay **TravelWell', 'live', 'verified', 'tropicalBeach', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"romance","expedition","ocean"}', '{}', '{"comfort","luxury"}', null, null, '{"key_facts":["Banderas Bay hosts ~500–700 humpback whales each winter; season ~Dec 8–Mar 23 (Source: mismaloyaxtreme.com, Accessed 2026-07-04)","Hotel Mousai is the only AAA Five-Diamond resort in Puerto Vallarta (Source: travellemming.com, Accessed 2026-07-04)","Conchas Chinas is PV''s premier villa enclave, the ''Beverly Hills of Puerto Vallarta'' (Source: casabayvillas.com, Accessed 2026-07-04)","Los Arcos National Park holds the deepest water in Banderas Bay for certified divers (Source: vallarta-adventures.com, Accessed 2026-07-04)","Served by PVR (Lic. Gustavo Díaz Ordaz Intl) with direct US/Canada/UK flights (Source: en.wikipedia.org, Accessed 2026-07-04)"],"safety":{"emergency":"911","hospital":"Hospital San Javier Marina (Level III, trauma-capable); Hospital CMQ (three 24/7 bilingual locations)","advisory_level":"L3","book_enabled":true,"tourist_zone_carveout":"Puerto Vallarta (named, no restrictions)","air_access_verified":"PVR (Lic. Gustavo Díaz Ordaz Intl)","malaria":"none in resort zone; dengue seasonal (rainy Jul–Oct)","yellow_fever":"none required"},"timing":{"peak":"Nov–Apr (dry; overlaps humpback season Dec–Mar)","shoulder":"May–Jun, late Oct","green":"Jul–Oct (rainy/hurricane season)","booking_lead":"Dec–Mar villas 4–6+ months; shoulder 6–10 weeks","off_season_specials":"Jul–Oct value campaign: beaches + diving + villa-with-chef (no whales)","event_peaks":"US/Canada winter holidays (late Dec–early Jan); spring break (Mar)","campaign_start":"Aug–Sep for whale/Romance (Dec–Mar arrivals); May–Jun for green-season value"},"jewels":[{"name":"Humpback panga at dawn, Banderas Bay","si_tag":"GEA","status":"live","hook":"~500–700 humpbacks breed within sight of shore Dec–Mar","bookable_category":"tour","tier":"comfort","commission_path":"DMC/tour affiliate ~8–15%","source":"https://mismaloyaxtreme.com/en/whale-watching-puerto-vallarta-2025-2026-guide/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"~500–700 humpbacks breed within sight of shore Dec–Mar","when":"Nov–Apr","commission":"DMC/tour affiliate ~8–15%","accessed":"2026-07-04"},{"name":"Los Arcos National Park dive","si_tag":"Ocean Adventures","status":"future","hook":"Deepest water in the bay — tunnels, rays, turtles","bookable_category":"tour","tier":"comfort","commission_path":"tour affiliate ~8–12%","source":"https://www.vallarta-adventures.com/en/tour/scuba-los-arcos (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Deepest water in the bay — tunnels, rays, turtles","when":"Nov–Apr","commission":"tour affiliate ~8–12%","accessed":"2026-07-04"},{"name":"Marietas Islands","si_tag":"Ocean Adventures","status":"future","hook":"Pacific mantas + reef fish + Hidden Beach","bookable_category":"tour","tier":"comfort","commission_path":"tour affiliate ~8–12%","source":"https://www.vallarta-adventures.com/en/tour/scuba-las-marietas-islands (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Pacific mantas + reef fish + Hidden Beach","when":"Nov–Apr","commission":"tour affiliate ~8–12%","accessed":"2026-07-04"},{"name":"Casa Kimberly","si_tag":"Romance & Honeymoons","status":"live","hook":"The Taylor/Burton love-story hotel, heart-shaped-tub suite","bookable_category":"hotel","tier":"luxury","commission_path":"hotel/host commission ~10%","source":"https://travellemming.com/hotels-in-puerto-vallarta/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"The Taylor/Burton love-story hotel, heart-shaped-tub suite","when":"Nov–Apr","commission":"hotel/host commission ~10%","accessed":"2026-07-04"},{"name":"Conchas Chinas villa with private chef","si_tag":"Romance & Honeymoons","status":"live","hook":"Hillside beachfront villa, chef/butler, minutes from Romantic Zone","bookable_category":"villa","tier":"luxury","commission_path":"villa-agency commission via host (MoR ~10%)","source":"https://villaexperience.com/city/puerto-vallarta/ (Accessed 2026-07-04)","timing":"Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Hillside beachfront villa, chef/butler, minutes from Romantic Zone","when":"Nov–Apr","commission":"villa-agency commission via host (MoR ~10%)","accessed":"2026-07-04"}],"faq":[{"q":"Is Puerto Vallarta safe to visit in 2026?","a":"Yes — freely bookable. Jalisco carries a US State Dept Level 3 advisory (May 29, 2026), but PV is a named carve-out with no travel restrictions, and it clears all three TWW gates: named carve-out + its own airport (PVR) + advisory disclosure. book_enabled=TRUE.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"Staying in the tourist zone, not the interior. Fly into PVR (no need to transit the restricted interior), remain within PV / the Banderas Bay resort corridor, and don''t self-drive into the Jalisco interior. Health-wise, dengue is seasonal in the Jul–Oct rains — use repellent — and there is no malaria in the resort zone.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"When and how can I see the whales?","a":"On a licensed panga, roughly Dec 8–Mar 23, best in the morning. Around 500–700 humpbacks arrive in Banderas Bay each winter to breed and calve within sight of shore; whales are federally protected, so keep the regulated distance and do not swim with them. Morning departures mean calmer seas.","source":"mismaloyaxtreme.com, 2026-07-04","si_tag":"expedition"},{"q":"Is Puerto Vallarta good for a honeymoon, and where''s the top end?","a":"Yes — it''s a mature honeymoon and destination-wedding market. The in-city ultra rung is narrow but real: Hotel Mousai is PV''s only AAA Five-Diamond (145 suites + 4 penthouses), and the 9-room Casa Kimberly is the Taylor/Burton love-story hotel. Peak is Nov–Apr; hold marquee rooms and villas early.","source":"travellemming.com, 2026-07-04","si_tag":"romance"},{"q":"Can beginners dive Los Arcos?","a":"Los Arcos is a certified-diver site, not a beginner pool — it holds the deepest water in Banderas Bay, with tunnels, arches, rays and turtles. Dive within your certification, and observe the DAN no-fly interval of 18–24 hours before boarding a flight from PVR. Marietas Islands is the other certified-reef option.","source":"vallarta-adventures.com, 2026-07-04","si_tag":"ocean-adventures-—-future"},{"q":"Where are the best villas?","a":"Conchas Chinas and Amapas. PV''s \"Beverly Hills\" hillside enclave holds beachfront estates with private chef and butler just 5–10 minutes from the Romantic Zone; book Dec–Mar (the whale-and-holiday peak) 4–6+ months ahead. Route villas as agency/host merchant-of-record, never net-rate resale.","source":"casabayvillas.com / villaexperience.com, 2026-07-04","si_tag":"tropical"}],"seo":{"meta_title":"Puerto Vallarta Travel Guide 2026 — Whales, Villas & Banderas Bay | TravelWell.World","meta_description":"Plan Puerto Vallarta: humpback whale season (Dec–Mar), luxury villas in Conchas Chinas, Five-Diamond resorts, and diving Los Arcos — with the Jalisco Level 3 advisory explained and PV''s named carve-out.","primary_keywords":["Puerto Vallarta travel","Puerto Vallarta whale watching","Puerto Vallarta luxury villas","is Puerto Vallarta safe 2026"],"long_tail":["Puerto Vallarta humpback whale season dates","Conchas Chinas villa rental with chef","Puerto Vallarta Level 3 advisory carve-out","diving Los Arcos Puerto Vallarta"],"search_language":"es-MX","local_keywords":["avistamiento de ballenas Puerto Vallarta","villas de lujo Conchas Chinas","Puerto Vallarta es seguro 2026","buceo Los Arcos Puerto Vallarta","hoteles todo incluido Puerto Vallarta"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"expedition","status":"live"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Hotel Mousai","why_ultra":"Only AAA Five-Diamond resort in PV; hilltop suites + penthouses over Banderas Bay","earning":"on application / via host","virtuoso_value_add":"verify Virtuoso/preferred; if listed, breakfast + credit + upgrade","mor":"hotel"},{"name":"Garza Blanca Preserve Resort & Spa","why_ultra":"Private-beach sister to Mousai; shared facilities","earning":"on application / via host","virtuoso_value_add":"verify","mor":"hotel"},{"name":"Casa Kimberly","why_ultra":"9-room Taylor/Burton icon, bay-view Taylor suite","earning":"host/hotel commission on application","virtuoso_value_add":"verify","mor":"hotel"},{"name":"Conchas Chinas / Amapas luxury villas (e.g. Villa Amapas South)","why_ultra":"~7,000 sq ft beachfront estate, chef/butler","earning":"villa-agency commission via host, on application","virtuoso_value_add":"n/a (villa)","mor":"agency/host (never net-rate resale)"},{"name":"One&Only Mandarina [Nayarit — state-line flag]","why_ultra":"Ultra resort in neighboring Riviera Nayarit, inside PV safety carve-out","earning":"on application / via host-Virtuoso","virtuoso_value_add":"verify","mor":"hotel"}],"source_verified":"2026-07-04","hero":{"query":"Puerto Vallarta, Mexico"},"geo":{"lat":20.6534,"lng":-105.2253}}'::jsonb, 85),
  ('puerto-viejo-costa-rica', '10S', 'Puerto Viejo (Southern Caribbean)', 'Costa Rica', 'Costa Rica''s Southern Caribbean **TravelWell', 'live', 'verified', 'tropicalBeach', 'Costa Rica', '{"tropical","expedition","culture","wildlife","ocean"}', '{"tropical"}', '{"essential","comfort"}', null, null, '{"key_facts":["Puerto Viejo de Talamanca is Costa Rica''s Southern Caribbean counter-culture coast: Afro-Caribbean + Bribri, reggae-slow beach towns, distinct from the Pacific side.","The Caribbean coast INVERTS the national weather pattern - driest and calmest in Sep-Oct and Feb-Mar, exactly when the Pacific is ''green season'' - a counter-seasonal selling point.","Cahuita National Park protects both a coral reef (guided snorkel only, ~$20pp) and a coastal rainforest walk with sloths, monkeys, iguanas and coatis.","Salsa Brava is an expert-only shallow reef break over sharp coral; beginners surf the Playa Cocles beach break; Punta Uva and Manzanillo are the calm swimming beaches.","Access is international via SJO (San Jose), then a ~4-4.5 hr drive southeast via Limon - a real distance, not a short transfer."],"safety":{"emergency":"911","ambulance_alt":"128 (Red Cross)","hospital":"24-hr private clinic in Puerto Viejo + public clinic Hone Creek (~5km); nearest hospital Limon (~1hr); major trauma routes to San Jose","medical_evacuation":"AirMed/Global Rescue-type air ambulance toward San Jose/repatriation; ~US$50,000 often full straight","advisory_level":"L2","book_enabled":true,"l2_disclosure":true,"petty_crime":"opportunistic theft is main risk (phones/wallets/purses); don''t leave beach valuables unattended, avoid poorly lit streets alone at night, don''t resist a robbery","air_access_verified":"SJO (San Jose) -> ~4-4.5 hr drive via Limon to Puerto Viejo (distance flag)","riptide":"Caribbean riptide risk; Salsa Brava = expert-only reef break over sharp coral; swim at calmer beaches (Punta Uva, Manzanillo)","wildlife":"snake/wildlife on jungle & national-park trails - go guided, stay on trail, no-touch","dengue":"seasonal mosquito-borne risk, occasional outbreaks; repellent advised","malaria":"low/localized; negligible in beach-town zone; relevant only for deep-forest hikes","water":"generally potable in Costa Rica incl. most of this zone; sensitive travelers/remote lodges may prefer bottled - confirm at property"},"timing":{"counter_seasonal_peak_1":"Sep-Oct (Caribbean INVERTS national pattern: driest/calmest, best Cahuita snorkel visibility, rates ~30% lower)","counter_seasonal_peak_2":"Feb-Mar (driest most-reliable beach weather; least rain in March ~175mm)","surf_curve":"Salsa Brava swell Dec-Mar (dry-season window)","green_wet_variance":"wettest in the between-season troughs (~May-Aug bracket + secondary Nov-Dec lift); sell insured/refundable, lead with wildlife+reef-between-fronts","events":"Limon Carnival every October (Limon city; soca/calypso/reggae; Puerto Viejo lodging hub) + local Puerto Viejo/Manzanillo calypso nights (confirm 2026 dates)","booking_window_lead_time":"Sep-Oct value 3-5 weeks; Feb-Mar dry peak 6-10 weeks; Limon-Carnival Oct lodging 4-8 weeks","fill_the_beds":"wet troughs lead with Jaguar Rescue Center, Sloth Sanctuary, Bribri cacao tour, indoor culture + reef/beach between fronts","campaign_start_trigger":"Sep-Oct counter-seasonal push fires mid-late Aug 2026 (headline); Feb-Mar + Salsa Brava fires late-Dec 2025/early-Jan 2026; Limon-Carnival fires late-Aug/early-Sep 2026","fire_date":"2026-08-17"},"jewels":[{"name":"Cahuita National Park - reef snorkel + coastal wildlife walk","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Guided coral-reef snorkel PLUS a rainforest walk with sloths, monkeys, iguanas and coatis - reef + rainforest in one park.","bookable_category":"guided snorkel + wildlife hike","commission_path":"local-operator direct / affiliate 4-8%; park entry ($5 Puerto Vargas) + guide fee (~$20pp) pass-through","source":"https://mytanfeet.com/costa-rica-national-park/cahuita-national-park-costa-rica/","si":"expedition","blurb":"Guided coral-reef snorkel PLUS a rainforest walk with sloths, monkeys, iguanas and coatis - reef + rainforest in one park.","commission":"local-operator direct / affiliate 4-8%; park entry ($5 Puerto Vargas) + guide fee (~$20pp) pass-through"},{"name":"Punta Uva + Playa Cocles + Punta Cocles beach corridor","si_tag":"Tropical Islands / Beaches","status":"live","tier":"essential","hook":"Ivory-sand corridor - Punta Uva the calm swim/snorkel jewel, Cocles the beginner surf beach.","bookable_category":"self-guided beach","commission_path":"none direct (drives lodging + F&B + kayak/surf attach)","source":"https://mytanfeet.com/costa-rica-beach-information/punta-uva-puerto-viejo/","si":"Tropical Islands / Beaches","blurb":"Ivory-sand corridor - Punta Uva the calm swim/snorkel jewel, Cocles the beginner surf beach.","commission":"none direct (drives lodging + F&B + kayak/surf attach)"},{"name":"Manzanillo / Gandoca-Manzanillo Wildlife Refuge","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"23,348-acre refuge from Punta Uva to Panama; 500+ ha protected reef, year-round dolphins, turtles, manatees, Manzanillo->Punta Mona coastal trail.","bookable_category":"guided snorkel/dolphin-watch + coastal hike","commission_path":"local-operator direct / affiliate; refuge entry pass-through","source":"https://costarica.org/beaches/caribbean/manzanillo/","si":"wildlife","blurb":"23,348-acre refuge from Punta Uva to Panama; 500+ ha protected reef, year-round dolphins, turtles, manatees, Manzanillo->Punta Mona coastal trail.","commission":"local-operator direct / affiliate; refuge entry pass-through"},{"name":"Jaguar Rescue Center","si_tag":"Wildlife & Nature","status":"future","tier":"essential","hook":"Rehab center for Caribbean wildlife - monkeys, sloths, kinkajous, toucans, macaws, snakes; guided tours.","bookable_category":"scheduled guided tour","commission_path":"affiliate / operator direct; admission largely pass-through/donation","source":"https://mylatinlife.com/puerto-viejo-talamanca-costa-rica-travel-guide/","si":"wildlife","blurb":"Rehab center for Caribbean wildlife - monkeys, sloths, kinkajous, toucans, macaws, snakes; guided tours.","commission":"affiliate / operator direct; admission largely pass-through/donation"},{"name":"Sloth Sanctuary (Cahuita)","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Sloth rescue + canoe wildlife-viewing tour near Cahuita.","bookable_category":"guided sanctuary + canoe tour","commission_path":"affiliate / operator direct; admission pass-through","source":"https://mylatinlife.com/puerto-viejo-talamanca-costa-rica-travel-guide/","si":"wildlife","blurb":"Sloth rescue + canoe wildlife-viewing tour near Cahuita.","commission":"affiliate / operator direct; admission pass-through"},{"name":"Bribri indigenous territory + cacao/chocolate tour","si_tag":"Culture & Heritage","status":"future","tier":"comfort","hook":"Living-Indigenous immersion in the Talamanca foothills - walk the cacao agroforest, ferment/roast/grind, medicinal plants, home-cooked meal, waterfall.","bookable_category":"community cultural tour","commission_path":"community-operator direct / affiliate; community fee pass-through","source":"https://williestourscostarica.com/tours-old/bribri-indigenous-village-chocolate-tour-medicinal-plants/","si":"culture","blurb":"Living-Indigenous immersion in the Talamanca foothills - walk the cacao agroforest, ferment/roast/grind, medicinal plants, home-cooked meal, waterfall.","commission":"community-operator direct / affiliate; community fee pass-through"},{"name":"Salsa Brava reef break (watch or expert-only surf)","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"One of Central America''s heaviest waves over shallow coral - a spectator draw, an expert-only ride Dec-Mar; beginners to Cocles.","bookable_category":"expert self-guided / beginner-beach coaching","commission_path":"affiliate on beginner surf lessons/rentals; watching free (F&B attach)","source":"https://www.kimkim.com/e/surf-lessons-at-salsa-brava-in-puerto-viejo-de-talamanca","si":"expedition","blurb":"One of Central America''s heaviest waves over shallow coral - a spectator draw, an expert-only ride Dec-Mar; beginners to Cocles.","commission":"affiliate on beginner surf lessons/rentals; watching free (F&B attach)"},{"name":"Punta Uva clear-kayak (jungle river + emerald coast)","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"Clear kayaks up the jungle river/coast spotting toucans, monkeys, iguanas, river turtles.","bookable_category":"guided clear-kayak","commission_path":"affiliate / operator direct","source":"https://caribesurcr.com/tour-item/clear-kayak-tour/","si":"ocean","blurb":"Clear kayaks up the jungle river/coast spotting toucans, monkeys, iguanas, river turtles.","commission":"affiliate / operator direct"},{"name":"Afro-Caribbean cuisine (rondon + rice-and-beans in coconut)","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The coast''s Creole table - rondon coconut-milk stew, rice-and-beans in coconut, calypso-culture kitchens.","bookable_category":"self-guided + food/culture tours","commission_path":"affiliate on food tours; otherwise F&B attach","source":"https://soullifetravel.net/bribri-chocolate-indigenous-culture-costa-rica/","si":"culture","blurb":"The coast''s Creole table - rondon coconut-milk stew, rice-and-beans in coconut, calypso-culture kitchens.","commission":"affiliate on food tours; otherwise F&B attach"},{"name":"Limon Carnival (October) + calypso nights","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"The coast''s flagship Afro-Caribbean festival (soca/calypso/reggae/parades) in Limon each October; Puerto Viejo lodging hub.","bookable_category":"self-guided + festival-week lodging","commission_path":"lodging AOR + affiliate on festival transfers","source":"https://www.takeyourbackpack.com/backpacking-in-costa-rica/visit-limon-carnival/","si":"culture","blurb":"The coast''s flagship Afro-Caribbean festival (soca/calypso/reggae/parades) in Limon each October; Puerto Viejo lodging hub.","commission":"lodging AOR + affiliate on festival transfers"}],"faq":[{"q":"Which Puerto Viejo beaches are safe for swimming?","a":"Head to Punta Uva and Manzanillo — the calm, gently-shelving beaches. Playa Cocles is a beginner-to-intermediate beach break for surfers, while Salsa Brava is an expert-only shallow reef break over sharp coral. Match the beach to the swimmer and heed local water conditions.","source":"kimkim.com, 2026-07-06","si_tag":"tropical"},{"q":"Do you need a guide to snorkel Cahuita National Park?","a":"Yes — Cahuita''s reef snorkel is guided-only (~US$20 pp); you can''t bring your own gear and go solo, single-use plastics are banned, and no-touch coral discipline applies. Book the guided boat snorkel for best visibility Mar–Apr and Aug–Oct.","source":"mytanfeet.com, 2026-07-06","si_tag":"expedition"},{"q":"Is Puerto Viejo good for a honeymoon?","a":"Yes, as barefoot-luxury rather than palace-luxury. The ceiling is premier-to-luxury boutique — Le Cameleon (SLH) from ~US$186/night, or the 7-bungalow Tierra de Sueños wellness hideaway in Playa Chiquita — jungle-beach seclusion, adults-leaning, no marble required.","source":"lecameleonhotel.com, 2026-07-06","si_tag":"romance"},{"q":"When is Limón Carnival, and can you base in Puerto Viejo for it?","a":"Yes. Limón Carnival runs every October (started 1949) in the port city of Limón — soca, calypso, reggae and parades — with Puerto Viejo a common lodging hub a short hop south; confirm exact 2026 dates on live tracking.","source":"takeyourbackpack.com, 2026-07-06","si_tag":"culture"},{"q":"Can you see sloths and dolphins around Puerto Viejo?","a":"Easily. The town is ringed by jungle, so sloths, monkeys and colorful birds show right off the coast road, and the 23,348-acre Gandoca-Manzanillo refuge holds year-round bottlenose and tucuxi dolphins plus four sea-turtle species (Mar–Jul).","source":"costarica.org, 2026-07-06","si_tag":"wildlife"},{"q":"Is Puerto Viejo safe right now?","a":"Yes, with standard caution. Costa Rica is U.S. Level 2 (issued Apr 2, 2026) for crime; opportunistic theft is the real, mundane risk. Don''t leave valuables unattended on the beach, avoid poorly-lit streets alone at night, don''t display wealth, and don''t resist a robbery.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"Can beginners surf Salsa Brava?","a":"No. Salsa Brava is an expert-only, powerful, shallow reef break over sharp coral — one of Central America''s heaviest waves — and it injures those who fall. Beginners and intermediates belong at the Playa Cocles beach break or a gentler beach; distinguish clearly at point of sale.","source":"kimkim.com, 2026-07-06","si_tag":"safety"},{"q":"How far is medical care if something goes wrong?","a":"A 24-hour private clinic in Puerto Viejo handles emergencies, with a public clinic in Hone Creek (~5 km) and the nearest large hospital in Limón (~1 hr); major trauma routes to San José. Air-evac cases can run ~US$50,000, often full straight — carry robust travel + air-evac insurance.","source":"puntauvarealty.com, 2026-07-06 · remax-oceansurf-cr.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Puerto Viejo de Talamanca, Costa Rica Travel Guide 2026 - Southern Caribbean, Sloths, Salsa Brava & Cahuita | TravelWell.World","meta_description":"Plan Costa Rica''s Southern Caribbean: Puerto Viejo de Talamanca, Cahuita reef & wildlife, Punta Uva & Manzanillo beaches, Salsa Brava surf, Bribri chocolate, boutique jungle-beach lodges, straight L2 safety, and the counter-seasonal Sep-Oct sweet spot.","slug":"puerto-viejo-costa-rica","jsonld_type":"TouristDestination","author_byline":"By David McCallister - commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"es-CR","primary_keywords":["Puerto Viejo Costa Rica travel guide","Southern Caribbean Costa Rica","Cahuita National Park snorkeling"],"local_keywords":["Puerto Viejo de Talamanca","Cahuita parque nacional","playas Caribe Sur Costa Rica","Punta Uva Costa Rica","refugio Gandoca-Manzanillo","tour de cacao Bribri","surf Salsa Brava","perezosos Puerto Viejo","Carnaval de Limon"],"hreflang":["en","es-CR"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"expedition","status":"live"},{"si":"culture","status":"future"},{"si":"wildlife","status":"future"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Le Cameleon Boutique Hotel","price_tier":"luxury","virtuoso":false,"slh_member":true,"earning":"on application / host-Virtuoso / SLH trade / Fora","mor_posture":true,"note":"Playa Cocles beachfront; Small Luxury Hotels of the World; 51 rooms + 7 suites + 3 villas; the coast''s ceiling","source":"https://www.lecameleonhotel.com/"},{"name":"Tierra de Suenos Lodge & Wellness Center","price_tier":"premier-luxury","virtuoso":false,"earning":"host-agency AOR / Fora","mor_posture":true,"note":"7 hardwood Caribbean bungalows, Playa Chiquita; wellness/yoga hideaway","source":"https://tierradesuenoslodge.com/"},{"name":"Namuwoki Lodge","price_tier":"premier","virtuoso":false,"earning":"host-agency AOR / Fora","mor_posture":true,"note":"17 bungalows/villas, Playa Chiquita (Bribri ''Home of the Jaguar''); spa + restaurant","source":"https://www.namuwoki.com/"},{"name":"Physis Caribbean Bed & Breakfast","price_tier":"comfort-premier","virtuoso":false,"earning":"host-agency AOR / direct / Fora","mor_posture":true,"note":"intimate 4-room owner-run luxury B&B, Cocles","source":"https://physiscaribbean.net/about/"}],"source_verified":"2026-07-06","hero":{"query":"Puerto Viejo (Southern Caribbean), Costa Rica"},"geo":{"lat":9.6558,"lng":-82.7549}}'::jsonb, 86),
  ('punta-del-este-uruguay', '10S', 'Punta del Este & the Atlantic Coast, Uruguay', 'Uruguay', 'Calm bay, open Atlantic **TravelWell', 'live', 'verified', 'tropicalBeach', 'Montevideo & The Atlantic Coast', '{"tropical","romance","culinary"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["US State Dept Level 2 - Exercise Increased Caution (Uruguay; advisory dated 2025-05-07); reason = crime (C indicator); high-crime departments incl. Maldonado (Punta''s).","Two beaches: Playa Mansa (calm bay, family/swimming) vs Playa Brava (Atlantic surf, strong currents; La Mano is the warning). Swim patrolled zones only on Brava.","Signature set-pieces: Casapueblo sunset Ceremonia al Sol, La Mano, José Ignacio + Vik hotels, Isla de Lobos sea lions, Mallmann''s Garzón + Bodega Garzón (Tannat).","Peak = late-Dec to mid-Jan jet-set season; NYE is the single biggest night; premium villas/NYE book 3-6 months out; January most expensive hotel month.","Air: PDP (Punta del Este) seasonal Dec-Feb; year-round via MVD (Montevideo) + ~1.5 hr transfer. Tap water potable."],"safety":{"emergency":"911","police":"109","ambulance":"105","fire":"104","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":{"seasonal":"PDP (Capitán Corbeta CA Curbelo Intl, Punta del Este — busiest Dec-Feb)","year_round_gateway":"MVD (Carrasco Intl, Montevideo) + ~1.5 hr road transfer"},"water":"potable","primary_hazard":"Atlantic surf / riptides on Playa Brava (swim patrolled zones only; use Mansa bay for families)","trauma_path":"Punta private clinics (Cantegril + seasonal) → Montevideo (Hospital Británico / Hospital Italiano) → US medevac for catastrophic cases","petty_crime":"low but real — motorcycle snatch-theft + distraction/pickpocketing (weighted to Montevideo/nightlife); avoid after-dark ATMs, use registered taxis/ride-apps"},"timing":{"peak":"late-Dec to mid-Jan (austral summer jet-set season — the money window; NYE the single hottest night)","peak_volume_note":"January = statistically most expensive hotel month","inflection_curve_start":"loads hard in Oct-Nov ahead of the holidays; top villas/NYE spoken for earlier","fire_date":"curve-start minus 1-2 weeks (~late Sep / early Oct for Dec-Jan peak); NYE + premium villas = 3-6 months lead (fire ~June-July)","shoulder":"Nov (late spring) and Mar (early autumn) — warm, thinner, better rates, much of the scene still open","low_season":"Jun-Aug (winter — cool, windswept, largely shuttered; deep-discount trough)","off_season_fill":"sell on price + José Ignacio/Garzón food-and-wine (Bodega Garzón, Mallmann) + Casapueblo + wellness/retreat quiet","events":[{"name":"New Year''s Eve (Reveillon) fireworks on the bay","date":"31 December","venue":"Playa Mansa horseshoe + ticketed beach events + hotel Reveillon"},{"name":"High-summer cultural season","months":"Dec-Feb","note":"concerts, ballet, exhibitions layered on the beach core"}]},"jewels":[{"name":"La Mano / Los Dedos (Playa Brava)","si_tag":"Tropical/Beaches","tier":"essential","commission_path":"free public sculpture; guided-tour affiliate + beach day","source":"https://viator.com/Punta-del-Este-attractions/Los-Dedos-Playa-Brava-La-Mano-en-la-Arena/d4906-a7129","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Uruguay''s most iconic image — Mario Irarrázabal''s 1982 hand clawing out of the Atlantic sand, doubling as the surf-warning and the definitive Punta photo","si":"Tropical/Beaches","blurb":"Uruguay''s most iconic image — Mario Irarrázabal''s 1982 hand clawing out of the Atlantic sand, doubling as the surf-warning and the definitive Punta photo","when":"late-Dec to mid-Jan","commission":"free public sculpture; guided-tour affiliate + beach day"},{"name":"Playa Mansa vs Playa Brava two-mood beach day","si_tag":"Tropical/Beaches","tier":"essential","commission_path":"content-led; beach-club/day-pass + watersports affiliate","source":"https://silvias-trips.com/punta-del-este-uruguay-beach/","hook":"Sell both: Mansa for family swimming and sunset; Brava for surfers and the scene","si":"Tropical/Beaches","blurb":"Sell both: Mansa for family swimming and sunset; Brava for surfers and the scene","commission":"content-led; beach-club/day-pass + watersports affiliate"},{"name":"Isla de Lobos sea-lion boat excursion","si_tag":"Tropical/Beaches","tier":"comfort","commission_path":"activities affiliate (Viator/GetYourGuide) / DMC boat charter","source":"https://www.tripadvisor.com/Attraction_Review-g294066-d2630506-Reviews-Isla_de_Lobos-Punta_del_Este_Maldonado_Department.html","hook":"~2-hr guided boat tour from the Punta port around the offshore reserve","si":"Tropical/Beaches","blurb":"~2-hr guided boat tour from the Punta port around the offshore reserve","commission":"activities affiliate (Viator/GetYourGuide) / DMC boat charter"},{"name":"Cabo Polonio wild-coast day (Rocha)","si_tag":"Tropical/Beaches","tier":"comfort","commission_path":"activities affiliate / DMC 4x4 day-tour","source":"https://www.daytours4u.com/en/cabo-polonio-mount-ombues-day-tour.html/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The off-grid, 4×4-only dune outpost and sea-lion refuge up the coast — the wild counterpoint to glamour Punta, best as a guided full-day","si":"Tropical/Beaches","blurb":"The off-grid, 4×4-only dune outpost and sea-lion refuge up the coast — the wild counterpoint to glamour Punta, best as a guided full-day","when":"late-Dec to mid-Jan","commission":"activities affiliate / DMC 4x4 day-tour"},{"name":"La Barra strip","si_tag":"Tropical/Beaches","tier":"comfort","commission_path":"villa MoR + activities/nightlife affiliate","source":"https://upscapetravel.com/destinations/uruguay/punta-del-este/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The wooden-bridge village east of the peninsula — surf, galleries, boutiques, and the late-night bar scene; the bridge to José Ignacio","si":"Tropical/Beaches","blurb":"The wooden-bridge village east of the peninsula — surf, galleries, boutiques, and the late-night bar scene; the bridge to José Ignacio","when":"late-Dec to mid-Jan","commission":"villa MoR + activities/nightlife affiliate"},{"name":"Casapueblo sunset + Ceremonia al Sol (Punta Ballena)","si_tag":"romance","tier":"comfort","commission_path":"entry non-commissionable; DMC/concierge sunset package + hotel stay","source":"https://www.guruguay.com/casapueblo-uruguay/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The most romantic set-piece on the coast — Páez Vilaró''s white citadel, the recorded farewell-to-the-sun poem over the Atlantic, sparkling wine on the terrace","si":"romance","blurb":"The most romantic set-piece on the coast — Páez Vilaró''s white citadel, the recorded farewell-to-the-sun poem over the Atlantic, sparkling wine on the terrace","when":"late-Dec to mid-Jan","commission":"entry non-commissionable; DMC/concierge sunset package + hotel stay"},{"name":"José Ignacio boho-luxe hideaway + Playa Vik","si_tag":"romance","tier":"luxury","commission_path":"Virtuoso/Fora consortia + villa MoR + DMC","source":"https://www.insidehook.com/travel/perfect-weekend-jose-ignacio-uruguay","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The prestige village as a honeymoon base — a Vik suite or a beach villa, dune beaches, art, and hush","si":"romance","blurb":"The prestige village as a honeymoon base — a Vik suite or a beach villa, dune beaches, art, and hush","when":"late-Dec to mid-Jan","commission":"Virtuoso/Fora consortia + villa MoR + DMC"},{"name":"NYE fireworks night on Playa Mansa","si_tag":"romance","tier":"comfort","commission_path":"ticketed-event MoR (La Fiesta Punta-class) + hotel NYE package","source":"https://lafiestapunta.com/en/la-punta-fiesta-english/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The 31 December bay-side fireworks along ~40 miles of coast — a once-in-a-lifetime proposal/anniversary night","si":"romance","blurb":"The 31 December bay-side fireworks along ~40 miles of coast — a once-in-a-lifetime proposal/anniversary night","when":"late-Dec to mid-Jan","commission":"ticketed-event MoR (La Fiesta Punta-class) + hotel NYE package"},{"name":"Parador La Huella fish-on-the-sand (José Ignacio)","si_tag":"RHN / Culinary","tier":"premier","commission_path":"direct reservation / DMC private experience","source":"https://www.roughguides.com/articles/best-restaurants-in-punta-del-este/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Fresh seafood on the beach at one of South America''s most famous restaurants — a beach-chic date night","si":"RHN / Culinary","blurb":"Fresh seafood on the beach at one of South America''s most famous restaurants — a beach-chic date night","when":"late-Dec to mid-Jan","commission":"direct reservation / DMC private experience"},{"name":"Francis Mallmann''s Restaurante Garzón (Garzón)","si_tag":"culinary","tier":"premier","commission_path":"direct reservation / DMC-packaged; Garzón hotel stay commissionable","source":"https://youshouldgohere.com/2024/09/francis-mallmann-garzon-uruguay/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"The celebrity chef''s fire-cooked temple in a revived near-ghost town — feels like Provence in Uruguay","si":"culinary","blurb":"The celebrity chef''s fire-cooked temple in a revived near-ghost town — feels like Provence in Uruguay","when":"late-Dec to mid-Jan","commission":"direct reservation / DMC-packaged; Garzón hotel stay commissionable"},{"name":"Bodega Garzón — winery + fire kitchen (Tannat)","si_tag":"culinary","tier":"premier","commission_path":"cellar-door direct / DMC wine-day package","source":"https://bodegagarzon.com/en/restaurant/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"A modern architectural showpiece winery known worldwide for its award-winning Tannat, with a Mallmann-influenced fire-based restaurant. Tasting + lunch is a marquee inland day","si":"culinary","blurb":"A modern architectural showpiece winery known worldwide for its award-winning Tannat, with a Mallmann-influenced fire-based restaurant. Tasting + lunch is a marquee inland day","when":"late-Dec to mid-Jan","commission":"cellar-door direct / DMC wine-day package"},{"name":"Tannat + Uruguayan-wine tasting circuit","si_tag":"culinary","tier":"comfort","commission_path":"DMC / activities affiliate","source":"https://bodegagarzon.com/en/restaurant/","timing":"late-Dec to mid-Jan","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Guided verticals of Tannat and the wider Maldonado/Garzón wine country — cellar-door or DMC-curated","si":"culinary","blurb":"Guided verticals of Tannat and the wider Maldonado/Garzón wine country — cellar-door or DMC-curated","when":"late-Dec to mid-Jan","commission":"DMC / activities affiliate"}],"faq":[{"q":"Which Punta del Este beach should I swim at — Mansa or Brava?","a":"Swim at Playa Mansa. The Mansa (calm Río de la Plata bay side) is gentle and family-friendly for swimming; Playa Brava faces the open Atlantic with strong waves and dangerous currents, best left to surfers and lifeguard-patrolled zones. The La Mano sculpture on Brava was built in 1982 as a literal warning about those currents.","source":"viator.com, 2026-07-07","si_tag":"tropical"},{"q":"Is Punta del Este good for a honeymoon?","a":"Yes — it is a co-primary romance destination. The boho-luxe play is a José Ignacio villa or a Vik suite, a Casapueblo sunset with sparkling wine (the Ceremonia al Sol has played daily since 1994), a fish-on-the-sand dinner at La Huella, and — if timing allows — NYE fireworks on the bay. José Ignacio is quieter and older-money than the peninsula''s party core.","source":"insidehook.com, 2026-07-07","si_tag":"romance"},{"q":"What''s the food-and-wine scene in Punta del Este?","a":"It is one of the region''s strongest. Parador La Huella grills the day''s catch on the José Ignacio sand (routinely on Latin America''s 50 Best); inland, Francis Mallmann''s Restaurante Garzón does open-fire cooking in a revived near-ghost town, and Bodega Garzón pours award-winning Tannat with a Mallmann-directed fire kitchen.","source":"roughguides.com, 2026-07-07","si_tag":"culinary"},{"q":"Is Punta del Este safe right now?","a":"Yes — it''s freely bookable. Uruguay carries a US State Department Level 2 advisory (\"Exercise Increased Caution,\" dated 2025-05-07) for crime — the same tier as France, Italy, and Spain. Punta''s department, Maldonado, is among the higher-crime ones, so standard urban precautions apply, but the real day-to-day risk here is the Atlantic surf, not street violence. Emergency: 911.","source":"travel.state.gov, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for in Punta del Este?","a":"The Atlantic surf. Playa Brava''s open-Atlantic waves and rip currents are the headline hazard — La Mano is literally the warning sign. Swim only in patrolled zones when lifeguards are on duty, and steer weak swimmers and children to the calm Playa Mansa bay side.","source":"viator.com, 2026-07-07","si_tag":"safety"},{"q":"Are the Isla de Lobos boat trip and Cabo Polonio dangerous?","a":"Not with a sanctioned operator. The ~2-hour Isla de Lobos crossing is open Atlantic — go on an operated launch with life jackets, and note that landing on the reserve is prohibited. Cabo Polonio is off-grid and reachable only by sanctioned 4×4 or horseback across the dunes; you cannot drive your own car in, so use an operator and treat it as a genuine wilderness day.","source":"daytours4u.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Punta del Este & the Atlantic Coast Travel Guide — Beaches, Casapueblo & José Ignacio | TravelWell","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"es-UY","long_tail_en":["things to do in Punta del Este","Casapueblo sunset ceremony","José Ignacio Uruguay","La Mano Punta del Este","Isla de Lobos boat tour sea lions","Punta del Este luxury villas","Parador La Huella","Bodega Garzón Francis Mallmann","Punta del Este New Year''s Eve","best time to visit Punta del Este","Cabo Polonio day trip","is Uruguay safe"],"local_keywords":["qué hacer en Punta del Este","atardecer en Casapueblo","José Ignacio","La Mano de Punta del Este","paseo a Isla de Lobos lobos marinos","alquiler de villas en Punta del Este","Parador La Huella","Bodega Garzón","Año Nuevo en Punta del Este","mejor época para visitar Punta del Este","Cabo Polonio"],"hreflang":["en","es-UY"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Fasano Punta del Este — Las Piedras","location":"inland Maldonado","tier":"ultra (resort-estate / AI anchor)","earning":"Fasano brand luxury / Amex FHR / Forbes — commission + amenities (UNVERIFIED %)"},{"name":"Playa Vik","location":"José Ignacio","tier":"ultra (Relais-tier)","earning":"Virtuoso / brand luxury — commission + amenities (UNVERIFIED %)"},{"name":"Estancia Vik","location":"José Ignacio","tier":"ultra (Relais-tier)","earning":"Virtuoso / brand luxury — commission + amenities (UNVERIFIED %)"},{"name":"Bahia Vik","location":"José Ignacio","tier":"ultra (Relais-tier)","earning":"Virtuoso / brand luxury — commission + amenities (UNVERIFIED %)"},{"name":"The Grand Hotel Punta del Este","location":"peninsula, Playa Brava","tier":"luxury","earning":"consortia / brand luxury — commission + amenities (UNVERIFIED %)"}],"source_verified":null,"hero":{"query":"Punta del Este & the Atlantic Coast, Uruguay, Uruguay"},"geo":{"lat":-34.9633,"lng":-54.9506}}'::jsonb, 87),
