ing":"year-round","timing_type":"ALWAYS-ON","hook":"stand with a foot in each hemisphere 26 km north","si":"culture","blurb":"stand with a foot in each hemisphere 26 km north","when":"year-round","commission":"Half-day tour affiliate"},{"name":"TelefériQo + Rucu Pichincha","si_tag":"expedition","tier":"essential","commission_path":"Ticket affiliate + guided-climb DMC","source":"https://www.secretflying.com/guides/quito/things-to-do/","timing":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"cable car to ~4,000 m on Pichincha, ~$8.50 adult; gateway to the Rucu summit scramble","si":"expedition","blurb":"cable car to ~4,000 m on Pichincha, ~$8.50 adult; gateway to the Rucu summit scramble","when":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","commission":"Ticket affiliate + guided-climb DMC"},{"name":"Cotopaxi National Park & Limpiopungo","si_tag":"expedition","tier":"comfort","commission_path":"DMC day-trip/mountaineering (park entry non-comm.)","source":"https://destinationlesstravel.com/day-trips-from-quito/","timing":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the 5,897 m active volcano 1h45 south; páramo, wild horses, the lagoon walk, and the guided glacier climb","si":"expedition","blurb":"the 5,897 m active volcano 1h45 south; páramo, wild horses, the lagoon walk, and the guided glacier climb","when":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","commission":"DMC day-trip/mountaineering (park entry non-comm.)"},{"name":"Quilotoa crater lake","si_tag":"expedition","tier":"comfort","commission_path":"Full-day DMC tour (rim fee non-comm.)","source":"https://destinationlesstravel.com/day-trips-from-quito/","timing":"[''Jun'', ''Jul'', ''Aug'', ''Sep'', ''Dec'']","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a 250 m-deep turquoise volcanic lake,