  ('sayulita-mexico', '10S', 'Sayulita & the Riviera Nayarit', 'Mexico', 'Nayarit''s boho surf pueblo magico **TravelWell', 'live', 'verified', 'tropicalBeach', 'Nayarit (Riviera Nayarit & Sayulita)', '{"tropical","expedition","romance","ocean","culture","family","wildlife"}', '{"tropical"}', '{"essential","comfort","luxury"}', null, null, '{"key_facts":["Sayulita is a Pueblo Magico (since 2015) and the boho surf-and-art anchor of the southern Riviera Nayarit.","Bahia de Banderas filters Pacific swell into a forgiving 2-4 ft sand-bottom beach break - one of Mexico''s best beginner surf classrooms.","Islas Marietas ''hidden beach'' (Playa del Amor) is permit-capped: ~116 people/day, closed Mondays and Tuesdays, licensed operators only, no self-swim, life jacket + no fins, no under-10s or over-65s.","Humpback whales fill Banderas Bay roughly mid-December to early April, peak January-February.","Sayulita''s rapid growth outran its sewage infrastructure; major upgrades and an offshore outfall have been built, beach under permanent sanitary surveillance - drink bottled water, swim the protected Los Muertos cove.","Air access via Puerto Vallarta International (PVR), ~24 miles / 38-60 min south."],"safety":{"emergency":"911","hospital":"Nearest full trauma: Puerto Vallarta private hospitals (CMQ / San Javier / Hospital Joya), ~40-60 min south; local Sayulita/Bucerias clinics stabilize/transfer; complex cases PVR -> US/Guadalajara air-evac","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","air_access_verified":true,"air_access_note":"Puerto Vallarta International (PVR), ~24 mi / 38-60 min south, in Jalisco but the regional gateway","riptides":"main beach + Los Muertos mellow; Patzcuarito/Carricitos open-Pacific and rip-prone (unsafe for beginner swimmers)","water":"bottled/purified only","dengue":"endemic seasonal risk, higher May-November","malaria":"not a practical risk in the tourist corridor","hurricane":"Pacific storm season ~June-October; insure/refundable summer rates"},"timing":{"peak":"Dec-Apr (dry season; whales Dec-Mar peak Jan-Feb; surf year-round; highest rates + crowds)","inflection":"November (dry weather arrives, thinner crowds, whales opening) and late April (emptying out)","green":"May-Oct (rainy/value; ~20-40% off; warmest ocean; calm beginner surf)","holiday_event_peaks":["Christmas week","New Year","Semana Santa (late Mar/early Apr - verify calendar)"],"booking_window_lead_time":"peak/holiday 3-5 months; shoulder (Nov/late-Apr) 2-4 months; green season near-walk-up","fire_date":"curve-start minus 1-2 weeks: open peak (Dec-Apr) campaigns early October; whale-season push early November; Semana Santa campaign by mid-January; green-season value push ~2 weeks before the May shoulder edge","fill_the_beds":"green months: lead beginner surf (calmest/warmest water), long-stay villa value, yoga/wellness retreats, Huichol workshops, San Pancho calm; hedge whale messaging until December"},"jewels":[{"name":"Sayulita main beach + Calle Delfines flag street","si_tag":"Tropical / Beaches","status":"live","tier":"essential","hook":"The town''s surf-beach heart under hundreds of papel-picado flags - go early.","bookable_category":"village stay + surf lesson","commission_path":"boutique-AOR + surf-operator affiliate; beach access pass-through","source":"https://themexicoedit.com/things-to-do-in-sayulita-mexico/","si":"Tropical / Beaches","blurb":"The town''s surf-beach heart under hundreds of papel-picado flags - go early.","commission":"boutique-AOR + surf-operator affiliate; beach access pass-through"},{"name":"Playa de los Muertos (family swimming cove)","si_tag":"Family","status":"future","tier":"essential","hook":"Rock-protected roped swim area, no surf/boat traffic - the safe kids'' beach.","bookable_category":"villa/boutique stay","commission_path":"villa MoR / boutique-AOR; access pass-through","source":"https://www.sayulitalife.com/sayulita-beaches","si":"family","blurb":"Rock-protected roped swim area, no surf/boat traffic - the safe kids'' beach.","commission":"villa MoR / boutique-AOR; access pass-through"},{"name":"Beginner surf lesson (sand-bottom break)","si_tag":"Global Expedition Adventures","status":"live","tier":"essential","hook":"Mexico''s best beginner classroom - forgiving filtered 2-4 ft waves.","bookable_category":"surf lesson","commission_path":"surf-operator affiliate / referral","source":"https://wildmex.com/activities/surf-lessons-sayulita-mexico/","si":"expedition","blurb":"Mexico''s best beginner classroom - forgiving filtered 2-4 ft waves.","commission":"surf-operator affiliate / referral"},{"name":"Huichol (Wixarika) art galleries + workshop","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Authentic beadwork/yarn-painting galleries and workshops with the stories behind the symbols.","bookable_category":"gallery + workshop","commission_path":"workshop affiliate; gallery purchases pass-through","source":"https://www.roughguides.com/articles/sacred-sites-and-unique-art-supporting-indigenous-huichol-culture/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Authentic beadwork/yarn-painting galleries and workshops with the stories behind the symbols.","when":"Dec-Apr","commission":"workshop affiliate; gallery purchases pass-through"},{"name":"Islas Marietas hidden beach (Playa del Amor)","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"Permit-capped national-park cove reached by swimming through a rock opening; booby colonies.","bookable_category":"licensed boat tour (permit required)","commission_path":"licensed-tour affiliate / DMC; permit ~US$3-5 pass-through","source":"https://wildmex.com/activities/tours-islas-marietas-playa-del-amor/","si":"ocean","blurb":"Permit-capped national-park cove reached by swimming through a rock opening; booby colonies.","commission":"licensed-tour affiliate / DMC; permit ~US$3-5 pass-through"},{"name":"Banderas Bay whale watching","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Morning humpback tours in the calving bay, Dec-Mar, peak Jan-Feb.","bookable_category":"whale-watch tour","commission_path":"affiliate 4-8% / DMC","source":"https://cms.vallartalifestyles.com/humpback-whale-season-begins-in-banderas-bay-and-beyond/","si":"wildlife","blurb":"Morning humpback tours in the calving bay, Dec-Mar, peak Jan-Feb.","commission":"affiliate 4-8% / DMC"},{"name":"San Pancho (San Francisco) — quiet-luxe + La Patrona polo","si_tag":"Romance & Honeymoons","status":"live","tier":"luxury","hook":"Slower, upmarket neighbor with polo (Oct-May), arts, wellness - a calm villa/honeymoon alternative.","bookable_category":"luxe villa + polo experience","commission_path":"DMC / luxury-villa MoR; polo affiliate","source":"https://mexiconewsdaily.com/mexico-living/play-the-sport-of-kings-in-laid-back-san-pancho-nayarit/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Slower, upmarket neighbor with polo (Oct-May), arts, wellness - a calm villa/honeymoon alternative.","when":"Dec-Apr","commission":"DMC / luxury-villa MoR; polo affiliate"},{"name":"Bucerias Thursday Art Walk","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"~17 galleries open 7-9pm Thursdays, artists creating live; quieter than Sayulita.","bookable_category":"art walk + DMC transfer/dinner","commission_path":"DMC transfer + dining affiliate; walk pass-through","source":"https://bestofbucerias.com/nearby/la-cruz-de-huanacaxtle/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"~17 galleries open 7-9pm Thursdays, artists creating live; quieter than Sayulita.","when":"Dec-Apr","commission":"DMC transfer + dining affiliate; walk pass-through"},{"name":"La Cruz de Huanacaxtle marina + Sunday Market","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"The Riviera''s largest artisan market on the marina docks (Sun, Nov-Apr) + sailing/charters hub.","bookable_category":"market + charter","commission_path":"charter/DMC; market pass-through","source":"https://www.rivieranayaritfun.com/la-cruz-sunday-market-la-cruz-mercado","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"The Riviera''s largest artisan market on the marina docks (Sun, Nov-Apr) + sailing/charters hub.","when":"Dec-Apr","commission":"charter/DMC; market pass-through"},{"name":"Rincon de Guayabitos family beach","si_tag":"Family","status":"future","tier":"essential","hook":"Old-school calm-water Mexican-family beach town off the surf-tourist track.","bookable_category":"local hotel + DMC transfer","commission_path":"DMC transfer / host-AOR; beach pass-through","source":"https://lacasitadelapenita.com/activities/markets-in-our-area/","si":"family","blurb":"Old-school calm-water Mexican-family beach town off the surf-tourist track.","commission":"DMC transfer / host-AOR; beach pass-through"}],"faq":[{"q":"Is Sayulita safe to visit right now?","a":"Yes — freely bookable. Nayarit carries a US State Dept Level 2 \"Exercise Increased Caution\" advisory, and the Puerto Vallarta / Riviera Nayarit tourist corridor (including Sayulita) is explicitly carved out with no US-government-employee restrictions. book_enabled=TRUE, no consent flow.","source":"travel.state.gov, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"Water and rip currents, not crime. Sayulita''s rapid growth outran its sewage plant — major upgrades and an offshore outfall have since been built and the beach is under permanent sanitary surveillance, but drink only bottled water. Swim the protected coves (main beach, Los Muertos); exposed Patzcuarito/Carricitos are rip-prone and unsafe for beginner swimmers.","source":"globalpressjournal.com / sayulitalife.com, 2026-07-07","si_tag":"safety"},{"q":"How good is Sayulita for learning to surf?","a":"It''s arguably Mexico''s best beginner classroom. Bahía de Banderas filters swell into a forgiving 2–4 ft sand-bottom break where you fall onto soft sand in waist-deep water, and surf works year-round (calmest and warmest in the green season). Take a lesson before attempting the reef/rock point breaks.","source":"mexicotravelandleisure.com / sayulitalife.com, 2026-07-07","si_tag":"expedition"},{"q":"Which beaches are best, and which are safe for kids?","a":"Los Muertos for families. It''s rock-protected with a roped swim area and no boat traffic — the safe kids'' cove — while the main beach fronts the surf and the papel-picado flag street; Rincón de Guayabitos up the coast is an old-school calm-water family beach. Avoid the open-Pacific rip-prone stretches.","source":"sayulitalife.com / themexicoedit.com, 2026-07-07","si_tag":"tropical"},{"q":"How do I visit the Islas Marietas Hidden Beach?","a":"Licensed operator only — you cannot swim or kayak in on your own. Access is capped at ~116/day, closed Mondays and Tuesdays, with life jacket and no fins mandatory and no children under 10 or adults over 65; you enter by jumping from the boat through a low rock opening. Book weeks ahead in season.","source":"vallartabyowner.com, 2026-07-07","si_tag":"ocean-adventures-—-future"},{"q":"What''s the Huichol art scene about?","a":"Living Indigenous art you can watch being made. Sayulita has deep Wixárika ties: galleries such as Galería Tanana (artist Cilau Valadez) and Tierra Huichol sell authentic beadwork and yarn paintings, and small workshops teach the beading and the meaning of the symbols. Gallery purchases are pass-through; workshops are the bookable wrapper.","source":"roughguides.com, 2026-07-07","si_tag":"culture-&-heritage-—-future"}],"seo":{"meta_title":"Sayulita & Riviera Nayarit Travel Guide 2026 — Surf, Marietas & Where to Stay | TravelWell.World","meta_description":"Plan Sayulita, Nayarit''s boho surf pueblo magico: beginner surf, Islas Marietas hidden-beach permit rules, whale season, Huichol art, straight water-infrastructure notes, Level 2 safety, and San Pancho/Bucerias/La Cruz jewels.","slug":"sayulita-mexico","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-07","search_language":"es-MX","local_keywords":["qué hacer en Sayulita","Islas Marietas playa escondida","Riviera Nayarit","mejor época para visitar Sayulita","clases de surf en Sayulita","arte huichol Sayulita","San Pancho Nayarit","ballenas Bahía de Banderas","Playa de los Muertos Sayulita","villas en Sayulita"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"Tropical / Beaches","status":"live"},{"si":"expedition","status":"live"},{"si":"romance","status":"live"},{"si":"ocean","status":"future"},{"si":"culture","status":"future"},{"si":"family","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Punta Mita — Four Seasons / St. Regis (own dossier)","price_tier":"ultra","virtuoso":true,"earning":"on application / via host-Virtuoso (Fora-eligible)","mor_posture":true,"note":"nearest branded ultra, ~25-30 min south; cross-ref its own dossier","source":"https://www.dreamexoticrentals.com/properties/LatinAmerica/mexico/PuntaMitaMexico-vacation-villas.htm"},{"name":"Amor Boutique Hotel / The Original Villa Amor (Sayulita)","price_tier":"luxury","virtuoso":false,"earning":"boutique-direct / host-AOR","mor_posture":true,"note":"31 oceanfront-hillside villas w/ plunge pools; on-village luxe anchor","source":"https://www.sayulitalife.com/amor-group-boutique-hotels"},{"name":"Haramara Retreat (Sayulita)","price_tier":"luxury","virtuoso":false,"earning":"retreat-direct / host-AOR","mor_posture":true,"note":"off-grid cliff-top wellness casitas, 360 yoga, open-air spa","source":"https://www.bontraveler.com/best-hotels-sayulita-mexico/"},{"name":"San Pancho luxe private villas","price_tier":"ultra","virtuoso":false,"earning":"on application / luxury-DMC or host villa AOR","mor_posture":true,"note":"full-service private villas in quiet-luxe neighbor; net-rate resale red","source":"https://www.puntademita-realestate.com/villasayulita18/"}],"source_verified":"2026-07-07","hero":{"query":"Sayulita & the Riviera Nayarit, Mexico"},"geo":{"lat":20.8697,"lng":-105.4419}}'::jsonb, 105),
  ('sian-kaan-mexico', '10S', 'Sian Ka''an Biosphere Reserve', 'Mexico', '*If it''s a place the Maya named "where the', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"expedition","wildlife","tropical"}', '{"tropical"}', '{"comfort","premier"}', null, null, '{"key_facts":["UNESCO World Heritage; largest reserve in Quintana Roo, ~5,000 km2 of forest/mangrove/wetland/reef","Signature: boat + life-vest float on 1,200-year-old hand-dredged Maya trade canals","Biodiversity: 300+ birds, 100+ mammals, 1,200 plants, 52 fish species","Guided-only, remote; Punta Allen coastal access ~4h on 56km unpaved road from Tulum","Fees non-commissionable: CONANP entry ~MX$218 (~US$12) + fixed Muyil boat ~MX$1,000/person"],"safety":{"emergency":"911","advisory_level":"L2","nearest_trauma":"Tulum/Playa del Carmen clinics; evac to Cancun for major trauma; Chetumal (south) alt","malaria":"NONE in tourist zone; dengue present - HIGH mosquito load (wetland/mangrove)","water":"bottled/purified","hurricane":"Jun-Nov, peak Aug-Oct","special_rule":"REMOTE + GUIDED-ONLY - do not enter interior independently; guides carry comms; PFD on canal float"},"timing":{"peak":"Dry season Nov-Apr (Dec-Apr optimal weather + best wildlife) - guided day-trip window","shoulder":"Nov and late-Apr edges","green":"Wet May-Oct (lush, fewer crowds, afternoon storms, hurricane overlap) - Tulum fill-the-beds","booking_window_lead_time":"2-4 weeks ahead in high season - DAILY VISITOR LIMITS cap seats (UNESCO biosphere rations access)","fill_the_beds":"No in-reserve beds; applies to Tulum pre/post stay - push May-Oct Tulum value + AM tours","holiday_event_peaks":"Dec holiday + New Year, Semana Santa compound the capped-seat crunch","campaign_start_trigger":"Early-book ~6-8 weeks ahead for Dec-Apr (seats capped); green-season Tulum-stay push May-Oct","source":"https://www.machupicchu.org/sian-kaan-biosphere-reserve-2026-unesco-world-heritage-day-trip-from-tulum.htm"},"jewels":[{"name":"Muyil ancient-Maya-canal float","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided expedition","commission_path":"affiliate ~4-8% (Viator/GYG) / DMC on application","source":"https://www.getyourguide.com/tulum-l248/tulum-sian-ka-an-biosphere-reserve-ancient-maya-canals-tour-t671649/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"boat run + life-vest drift on 1,200-yr-old Maya-dredged canals ·","si":"expedition","blurb":"boat run + life-vest drift on 1,200-yr-old Maya-dredged canals ·","when":"Dry season Nov-Apr","commission":"affiliate ~4-8% (Viator/GYG) / DMC on application"},{"name":"Guided lagoon boat expedition","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided boat tour","commission_path":"guided-tour affiliate / DMC (Mexico Kan Tours)","source":"https://www.mexicokantours.com/sian-kaan-adventure","si":"expedition","commission":"guided-tour affiliate / DMC (Mexico Kan Tours)"},{"name":"Kayak + snorkel Campechen lagoon","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable_category":"guided kayak/snorkel","commission_path":"affiliate/DMC","source":"https://www.mexicokantours.com/sian-kaan-adventure","si":"expedition","commission":"affiliate/DMC"},{"name":"Birding day (300+ species)","si_tag":"Wildlife & Nature","status":"future","tier":"premier","bookable_category":"specialist nature tour","commission_path":"on application, small-group premium","source":"https://lifeontheroam.com/sian-kaan-biosphere-reserve/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","when":"Dry season Nov-Apr","commission":"on application, small-group premium"},{"name":"Punta Allen coastal / sandbar","si_tag":"Tropical Islands","status":"future","tier":"comfort","bookable_category":"guided overland/boat","commission_path":"DMC/guide on application (~4h unpaved road)","source":"https://www.thoroughlytravel.com/sian-kaan-biosphere-reserve/","timing":"Dry season Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"Dry season Nov-Apr","commission":"DMC/guide on application (~4h unpaved road)"}],"faq":[{"q":"Is Sian Ka''an safe to visit right now?","a":"Yes — freely bookable, no hold. Sian Ka''an sits in Quintana Roo, which carries a standard US State Dept Level 2 \"Exercise Increased Caution\" (dated 2026-05-29). The real safety planning here is about remoteness, not crime: go guided-only, never enter the interior independently, and know that higher-acuity care is back in Tulum/Playa del Carmen, with major trauma evacuated to Cancún.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"What''s the real risk to plan for in Sian Ka''an?","a":"Remoteness, heat and mosquitoes — not marine hazards or crime. This is a mangrove/wetland reserve, so the mosquito load is high (repellent, cover up, especially dawn/dusk and rainy season), and sun, heat and dehydration are the genuine risks on a long, unpaved-road day. There is no interior infrastructure — carry water and travel with a comms-equipped guide.","source":"lifeontheroam.com / travel.state.gov, 2026-07-04","si_tag":"safety"},{"q":"Is the mangrove canal float safe?","a":"Yes, on the guided product — it is a gentle, life-vest drift, not a hazardous swim. The float uses a PFD as standard, and the mangrove channel maze is guided-only because it is non-navigable independently. There is no dive component and no marine hazard; the discipline is simply staying with your comms-equipped guide and respecting the protected water.","source":"lifeontheroam.com, 2026-07-04","si_tag":"safety"},{"q":"What is the signature Sian Ka''an experience?","a":"The Muyil canal float. A boat runs you down ancient trade canals hand-dredged by Maya mariners over 1,200 years ago, then you drift downstream in a life vest on the natural current through mangrove lagoons — a natural lazy river. It is best in the calmer morning (fewer bugs), and bundled tours include transport, meals and an expert guide.","source":"getyourguide.com / lifeontheroam.com, 2026-07-04","si_tag":"expedition"},{"q":"What wildlife can I see in Sian Ka''an?","a":"A great deal — the reserve''s four ecosystems host 300+ bird species, 100+ mammals, 1,200 plants and 52 fish species, with a good chance of dolphins on the lagoon runs. Dedicated dawn birding tours are the way to see the most; wildlife is the reserve''s purpose-built anchor, so book a naturalist-guided product rather than a bare boat ride.","source":"lifeontheroam.com, 2026-07-04","si_tag":"wildlife"},{"q":"How do you actually visit Sian Ka''an, and can I stay inside?","a":"As a guided day trip from Tulum — you cannot sleep in the biosphere, as there is no lodging of any kind inside. Access is guided-only with rationed daily visitor limits, so book 2–4 weeks ahead in high season. Note the fixed Muyil boat driver is transport-only; if you want interpretation, book a nature-guide product, not the bare boat fee.","source":"machupicchu.org / roamingaroundtheworld.com, 2026-07-04","si_tag":"planning"},{"q":"When is the best time to visit Sian Ka''an?","a":"November–April, the dry season, is best — Dec–April brings optimal weather and the best wildlife viewing. Whatever the season, morning tours are calmer with fewer bugs; the May–October wet season is lush and quieter but brings afternoon storms and hurricane overlap (Jun–Nov). Because seats are capped, book earliest for the Dec–April and holiday windows.","source":"machupicchu.org / lifeontheroam.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Sian Ka''an Biosphere Reserve: UNESCO Wetlands Tour","meta_description":"Sian Ka''an - UNESCO biosphere south of Tulum: float 1,200-year-old Maya canals, birds and mangroves. Guided-only, remote; how and when to go.","slug":"sian-kaan-mexico","primary_keyword":"Sian Ka''an Biosphere Reserve","long_tail":["Sian Ka''an Muyil canal tour","Sian Ka''an from Tulum","Sian Ka''an boat tour","Sian Ka''an birding","Punta Allen Sian Ka''an"],"search_language":"bilingual (en + es-MX)","local_keywords":["Reserva de la Biosfera Sian Ka''an","Sian Ka''an desde Tulum","canales mayas Muyil","tour Muyil Sian Ka''an","Sian Ka''an que hacer","avistamiento de aves Sian Ka''an","Punta Allen Sian Ka''an"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister - commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"wildlife","status":"future"},{"si":"tropical","status":"future"}],"ultra":[],"source_verified":"2026-07-04","hero":{"query":"Sian Ka''an Biosphere Reserve, Mexico"},"geo":{"lat":19.5333,"lng":-87.6167}}'::jsonb, 106)
